CREATE CACHED TABLE "PUBLIC"."REPORT_CARD"(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1 RESTART WITH 159) SELECTIVITY 100 NOT NULL,
    "CREATED_AT" TIMESTAMP WITH TIME ZONE SELECTIVITY 100 NOT NULL,
    "UPDATED_AT" TIMESTAMP WITH TIME ZONE SELECTIVITY 70 NOT NULL,
    "NAME" CHARACTER VARYING(254) SELECTIVITY 87 NOT NULL,
    "DESCRIPTION" CHARACTER LARGE OBJECT,
    "DISPLAY" CHARACTER VARYING(254) SELECTIVITY 13 NOT NULL,
    "DATASET_QUERY" CHARACTER LARGE OBJECT NOT NULL,
    "VISUALIZATION_SETTINGS" CHARACTER LARGE OBJECT NOT NULL,
    "CREATOR_ID" INTEGER SELECTIVITY 1 NOT NULL,
    "DATABASE_ID" INTEGER SELECTIVITY 1 NOT NULL,
    "TABLE_ID" INTEGER SELECTIVITY 6,
    "QUERY_TYPE" CHARACTER VARYING(16) SELECTIVITY 3,
    "ARCHIVED" BOOLEAN DEFAULT FALSE SELECTIVITY 3 NOT NULL,
    "COLLECTION_ID" INTEGER SELECTIVITY 15 COMMENT 'Optional ID of Collection this Card belongs to.',
    "PUBLIC_UUID" CHARACTER(36) SELECTIVITY 1 COMMENT 'Unique UUID used to in publically-accessible links to this Card.',
    "MADE_PUBLIC_BY_ID" INTEGER SELECTIVITY 1 COMMENT 'The ID of the User who first publically shared this Card.',
    "ENABLE_EMBEDDING" BOOLEAN DEFAULT FALSE SELECTIVITY 1 COMMENT 'Is this Card allowed to be embedded in different websites (using a signed JWT)?' NOT NULL,
    "EMBEDDING_PARAMS" CHARACTER LARGE OBJECT COMMENT 'Serialized JSON containing information about required parameters that must be supplied when embedding this Card.',
    "CACHE_TTL" INTEGER SELECTIVITY 1 COMMENT 'The maximum time, in seconds, to return cached results for this Card rather than running a new query.',
    "RESULT_METADATA" CHARACTER LARGE OBJECT COMMENT 'Serialized JSON containing metadata about the result columns from running the query.',
    "COLLECTION_POSITION" SMALLINT SELECTIVITY 15 COMMENT 'Optional pinned position for this item in its Collection. NULL means item is not pinned.',
    "ENTITY_ID" CHARACTER(21) SELECTIVITY 100 COMMENT 'Random NanoID tag for unique identity.',
    "PARAMETERS" CHARACTER LARGE OBJECT COMMENT 'List of parameter associated to a card',
    "PARAMETER_MAPPINGS" CHARACTER LARGE OBJECT COMMENT 'List of parameter associated to a card',
    "COLLECTION_PREVIEW" BOOLEAN DEFAULT TRUE SELECTIVITY 1 COMMENT 'Indicating whether the card should be visualized in the collection preview' NOT NULL,
    "METABASE_VERSION" CHARACTER VARYING(100) SELECTIVITY 3 COMMENT 'Metabase version used to create the card.',
    "TYPE" CHARACTER VARYING(16) DEFAULT 'question' SELECTIVITY 4 COMMENT 'The type of card, could be ''question'', ''model'', ''metric''' NOT NULL,
    "INITIALLY_PUBLISHED_AT" TIMESTAMP WITH TIME ZONE SELECTIVITY 1 COMMENT 'The timestamp when the card was first published in a static embed',
    "CACHE_INVALIDATED_AT" TIMESTAMP WITH TIME ZONE SELECTIVITY 80 COMMENT 'An invalidation time that can supersede cache_config.invalidated_at',
    "LAST_USED_AT" TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP SELECTIVITY 60 COMMENT 'The timestamp of when the card is last used' NOT NULL,
    "VIEW_COUNT" INTEGER DEFAULT 0 SELECTIVITY 63 COMMENT 'Keeps a running count of card views' NOT NULL,
    "ARCHIVED_DIRECTLY" BOOLEAN DEFAULT FALSE SELECTIVITY 3 COMMENT 'Was this thing trashed directly' NOT NULL,
    "DATASET_QUERY_METRICS_V2_MIGRATION_BACKUP" CHARACTER LARGE OBJECT COMMENT 'The copy of dataset_query before the metrics v2 migration',
    "SOURCE_CARD_ID" INTEGER SELECTIVITY 16 COMMENT 'The ID of the model or question this card is based on',
    "DASHBOARD_ID" INTEGER SELECTIVITY 7 COMMENT 'The dashboard that owns the card, if it is a dashboard-internal card.',
    "CARD_SCHEMA" INTEGER DEFAULT '20' SELECTIVITY 1 COMMENT 'Arbitrary revision number for how we store queries in report_card' NOT NULL
);           
