INSERT INTO SYSTEM_LOB_STREAM VALUES(53, 0, '{"description":null,"archived":false,"collection_position":10,"source_card_id":null,"table_id":null,"result_metadata":[{"name":"id","database_type":"uuid","base_type":"type/UUID","display_name":"id","semantic_type":"type/PK","field_ref":["field","id",{"base-type":"type/UUID"}]},{"name":"name","database_type":"text","base_type":"type/Text","display_name":"name","semantic_type":"type/Name","field_ref":["field","name",{"base-type":"type/Text"}]},{"name":"parent_id","database_type":"uuid","base_type":"type/UUID","display_name":"parent_id","field_ref":["field","parent_id",{"base-type":"type/UUID"}],"semantic_type":null},{"name":"location_type","database_type":"text","base_type":"type/Text","display_name":"location_type","semantic_type":null,"field_ref":["field","location_type",{"base-type":"type/Text"}]},{"name":"full_path","database_type":"text","base_type":"type/Text","display_name":"full_path","field_ref":["field","full_path",{"base-type":"type/Text"}],"semantic_type":"type/City"},{"name":"level","database_type":"int4","base_type":"type/Integer","display_name":"level","field_ref":["field","level",{"base-type":"type/Integer"}],"semantic_type":null},{"name":"level_id","database_type":"text","base_type":"type/Text","display_name":"level_id","field_ref":["field","level_id",{"base-type":"type/Text"}],"semantic_type":null},{"name":"level_1_name","database_type":"text","base_type":"type/Text","display_name":"level_1_name","field_ref":["field","level_1_name",{"base-type":"type/Text"}],"semantic_type":"type/State"},{"name":"level_2_name","database_type":"text","base_type":"type/Text","display_name":"level_2_name","field_ref":["field","level_2_name",{"base-type":"type/Text"}],"semantic_type":"type/City"},{"name":"level_3_name","database_type":"text","base_type":"type/Text","display_name":"level_3_name","field_ref":["field","level_3_name",{"base-type":"type/Text"}],"semantic_type":null},{"name":"level_4_name","database_type":"text","base_type":"type/Text","display_name":"level_4_name","field_ref":["field","level_4_name",{"base-type":"type/Text"}],"semantic_type":null},{"name":"level_5_name","database_type":"text","base_type":"type/Text","display_name":"level_5_name","field_ref":["field","level_5_name",{"base-type":"type/Text"}],"semantic_type":null},{"name":"level_6_name","database_type":"text","base_type":"type/Text","display_name":"level_6_name","field_ref":["field","level_6_name",{"base-type":"type/Text"}],"semantic_type":null},{"name":"level_7_name","database_type":"text","base_type":"type/Text","display_name":"level_7_name","field_ref":["field","level_7_name",{"base-type":"type/Text"}],"semantic_type":null},{"name":"level_8_name","database_type":"text","base_type":"type/Text","display_name":"level_8_name","field_ref":["field","level_8_name",{"base-type":"type/Text"}],"semantic_type":null},{"name":"level_9_name","database_type":"text","base_type":"type/Text","display_name":"level_9_name","field_ref":["field","level_9_name",{"base-type":"type/Text"}],"semantic_type":null},{"name":"level_10_name","database_type":"text","base_type":"type/Text","display_name":"level_10_name","field_ref":["field","level_10_name",{"base-type":"type/Text"}],"semantic_type":null}],"card_schema":22,"database_id":2,"enable_embedding":false,"collection_id":null,"query_type":"native","name":"Locations","type":"model","embedding_params":null,"cache_ttl":null,"dataset_query":{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE location_path AS (\n  SELECT\n    l.id,\n    l.parent_id,\n    l.name,\n    l.name::text AS path,\n    1 AS level,\n    CASE\n      WHEN ll.id IS NOT NULL THEN jsonb_build_object(ll.id::text, l.name)\n      ELSE ''{}''::jsonb\n    END AS level_map\n  FROM analytics.locations l\n  LEFT JOIN analytics.location_levels ll ON ll.level = 1\n  WHERE l.parent_id IS NULL\n\n  UNION ALL\n\n  SELECT\n    l.id,\n    l.parent_id,\n    l.name,\n    lp.path || '','' || l.name,\n    lp.level + 1 AS level,\n    lp.level_map\n      || CASE\n           WHEN ll.id IS NOT NULL THEN jsonb_build_object(ll.id::text, l.name)\n          ', NULL);     
INSERT INTO SYSTEM_LOB_STREAM VALUES(53, 1, ' ELSE ''{}''::jsonb\n         END AS level_map\n  FROM analytics.locations l\n  JOIN location_path lp ON l.parent_id = lp.id\n  LEFT JOIN analytics.location_levels ll ON ll.level = lp.level + 1\n),\npivot AS (\n  SELECT\n    lp.id,\n    MAX(j.value) FILTER (WHERE ll2.level = 1)  AS level_1_name,\n    MAX(j.value) FILTER (WHERE ll2.level = 2)  AS level_2_name,\n    MAX(j.value) FILTER (WHERE ll2.level = 3)  AS level_3_name,\n    MAX(j.value) FILTER (WHERE ll2.level = 4)  AS level_4_name,\n    MAX(j.value) FILTER (WHERE ll2.level = 5)  AS level_5_name,\n    MAX(j.value) FILTER (WHERE ll2.level = 6)  AS level_6_name,\n    MAX(j.value) FILTER (WHERE ll2.level = 7)  AS level_7_name,\n    MAX(j.value) FILTER (WHERE ll2.level = 8)  AS level_8_name,\n    MAX(j.value) FILTER (WHERE ll2.level = 9)  AS level_9_name,\n    MAX(j.value) FILTER (WHERE ll2.level = 10) AS level_10_name\n  FROM location_path lp\n  CROSS JOIN LATERAL jsonb_each_text(lp.level_map) AS j(key, value)\n  JOIN analytics.location_levels ll2 ON ll2.id::text = j.key\n  GROUP BY lp.id\n)\nSELECT\n  l.*,\n  lp.path  AS full_path,\n  lp.level,\n  ll.id    AS level_id,\n  p.level_1_name,  p.level_2_name,  p.level_3_name,  p.level_4_name,  p.level_5_name,\n  p.level_6_name,  p.level_7_name,  p.level_8_name,  p.level_9_name,  p.level_10_name\nFROM analytics.locations l\nJOIN location_path lp ON l.id = lp.id\nLEFT JOIN analytics.location_levels ll ON ll.level = lp.level\nLEFT JOIN pivot p ON p.id = l.id;"}},"parameter_mappings":[],"display":"table","archived_directly":false,"collection_preview":true,"visualization_settings":{"table.pivot_column":"created_at","table.cell_column":"valid_until"},"parameters":[],"dashboard_id":null}', NULL);               
