INSERT INTO SYSTEM_LOB_STREAM VALUES(54, 1, 'nb","base_type":"type/JSON","display_name":"content","field_ref":["field","content",{"base-type":"type/JSON"}],"semantic_type":null}],"card_schema":22,"database_id":2,"enable_embedding":false,"collection_id":7,"query_type":"native","name":"Printed + Registered","type":"model","embedding_params":null,"cache_ttl":null,"dataset_query":{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH printed AS (\n  SELECT *\n  FROM analytics.event_actions\n  WHERE action_type = ''PRINT_CERTIFICATE''\n),\nregistered AS (\n  SELECT *\n  FROM analytics.event_actions\n  WHERE action_type = ''REGISTER''\n)\n-- all printed, plus registered that are not printed\nSELECT p.*\nFROM printed p\nUNION ALL\nSELECT r.*\nFROM registered r\nLEFT JOIN printed p USING (event_id)\nWHERE p.event_id IS NULL;"}},"parameter_mappings":[],"display":"table","archived_directly":false,"collection_preview":true,"visualization_settings":{"table.pivot_column":"event_type","table.cell_column":"content"},"parameters":[],"dashboard_id":null}', NULL);       
