INSERT INTO "PUBLIC"."REVISION" VALUES
(650, 'Card', 156, 1, TIMESTAMP WITH TIME ZONE '2025-10-16 09:28:43.277798+03', '{"description":null,"archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"card_schema":22,"database_id":2,"enable_embedding":false,"collection_id":8,"query_type":"native","name":"Completeness rate","type":"question","embedding_params":null,"cache_ttl":null,"dataset_query":{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH top_level_locations AS (\n  SELECT name\n  FROM analytics.locations\n  WHERE parent_id IS NULL\n),\npopulation_sum AS (\n  SELECT \n    SUM(total_population) AS total_population\n  FROM \n    analytics.location_statistics s\n  JOIN \n    top_level_locations l ON s.name = l.name\n  WHERE \n    s.year = 2025\n),\nbirth_rate AS (\n  SELECT \n    AVG(crude_birth_rate) AS country_birth_rate\n  FROM \n    analytics.location_statistics\n  WHERE \n    year = 2025\n),\nregistered_births AS (\n  SELECT \n    COUNT(*) AS registered_count\n  FROM \n    analytics.event_actions\n  WHERE \n    action_type = ''REGISTER''\n    AND event_type = ''birth''\n    AND (created_at::date - (declaration->>''child_dob'')::date) < 365\n)\nSELECT \n  r.registered_count / (p.total_population / 1000 * b.country_birth_rate) * 100 AS registered_birth_percentage\nFROM \n  registered_births r,\n  birth_rate b,\n  population_sum p;"}},"parameter_mappings":[],"display":"gauge","archived_directly":false,"collection_preview":true,"visualization_settings":{"gauge.segments":[{"min":0,"max":0.25,"color":"hsla(358, 71%, 62%, 1)","label":""},{"min":0.25,"max":0.75,"color":"#F9CF48","label":""},{"min":0.75,"max":1,"color":"#84BB4C","label":""}],"column_settings":{"[\"name\",\"registered_birth_percentage\"]":{"suffix":"%"}}},"parameters":[],"dashboard_id":12}', FALSE, TRUE, NULL, FALSE, 'v0.56.4 (aeaacd0)'),
