(660, 'Card', 156, 1, TIMESTAMP WITH TIME ZONE '2025-10-17 14:27:34.020766+03', '{"description":null,"archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"card_schema":22,"database_id":2,"enable_embedding":false,"collection_id":8,"query_type":"native","name":"Completeness rate","type":"question","embedding_params":null,"cache_ttl":null,"dataset_query":{"database":2,"type":"native","native":{"template-tags":{"year":{"type":"text","name":"year","id":"be1ae479-6da3-4c17-b7fe-e412a701c0b7","display-name":"Year"}},"query":"WITH top_level_locations AS (\n  SELECT name\n  FROM analytics.locations\n  WHERE parent_id IS NULL\n),\npopulation_sum AS (\n  SELECT \n    SUM(total_population) AS total_population\n  FROM \n    analytics.location_statistics s\n  JOIN \n    top_level_locations l ON s.name = l.name\n  WHERE \n    s.year = [[{{year}}]]\n),\nbirth_rate AS (\n  SELECT \n    AVG(crude_birth_rate) AS country_birth_rate\n  FROM \n    analytics.location_statistics\n  WHERE \n    year = [[{{year}}]]\n),\nregistered_births AS (\n  SELECT \n    COUNT(*) AS registered_count\n  FROM \n    analytics.event_actions\n  WHERE \n    action_type = ''REGISTER''\n    AND event_type = ''birth''\n    AND (created_at::date - (declaration->>''child_dob'')::date) < 365\n)\nSELECT \n  r.registered_count / (p.total_population / 1000 * b.country_birth_rate) * 100 AS registered_birth_percentage\nFROM \n  registered_births r,\n  birth_rate b,\n  population_sum p;"}},"parameter_mappings":[],"display":"gauge","archived_directly":false,"collection_preview":true,"visualization_settings":{"gauge.segments":[{"min":0,"max":25,"color":"hsla(358, 71%, 62%, 1)","label":""},{"min":25,"max":75,"color":"#F9CF48","label":""},{"min":75,"max":100,"color":"#84BB4C","label":""}],"column_settings":{"[\"name\",\"registered_birth_percentage\"]":{"suffix":"%"}}},"parameters":[{"id":"be1ae479-6da3-4c17-b7fe-e412a701c0b7","type":"string/=","target":["variable",["template-tag","year"]],"name":"Year","slug":"year","isMultiSelect":false}],"dashboard_id":12}', FALSE, FALSE, NULL, FALSE, 'v0.56.4 (aeaacd0)');            
