INSERT INTO SYSTEM_LOB_STREAM VALUES(87, 1, '":"type/Text"}],"semantic_type":null},{"name":"level_8_name","database_type":"text","base_type":"type/Text","display_name":"level_8_name","field_ref":["field","level_8_name",{"base-type":"type/Text"}],"semantic_type":null},{"name":"level_9_name","database_type":"text","base_type":"type/Text","display_name":"level_9_name","field_ref":["field","level_9_name",{"base-type":"type/Text"}],"semantic_type":null},{"name":"level_10_name","database_type":"text","base_type":"type/Text","display_name":"level_10_name","field_ref":["field","level_10_name",{"base-type":"type/Text"}],"semantic_type":null}],"card_schema":22,"database_id":2,"enable_embedding":false,"collection_id":null,"query_type":"native","name":"Locations","type":"model","embedding_params":null,"cache_ttl":null,"dataset_query":{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE administrative_area_path AS (\n    -- roots\n    SELECT\n        aa.id,\n        aa.parent_id,\n        aa.name,\n        aa.name::text AS administrative_area_path,\n        1 AS level\n    FROM app.administrative_areas aa\n    WHERE aa.parent_id IS NULL\n\n    UNION ALL\n\n    -- descendants\n    SELECT\n        aa.id,\n        aa.parent_id,\n        aa.name,\n        aap.administrative_area_path || '','' || aa.name,\n        aap.level + 1\n    FROM app.administrative_areas aa\n    JOIN administrative_area_path aap\n        ON aa.parent_id = aap.id\n),\n\npivot AS (\n    SELECT\n        id,\n\n        split_part(administrative_area_path, '','', 1)  AS level_1_name,\n        split_part(administrative_area_path, '','', 2)  AS level_2_name,\n        split_part(administrative_area_path, '','', 3)  AS level_3_name,\n        split_part(administrative_area_path, '','', 4)  AS level_4_name,\n        split_part(administrative_area_path, '','', 5)  AS level_5_name,\n        split_part(administrative_area_path, '','', 6)  AS level_6_name,\n        split_part(administrative_area_path, '','', 7)  AS level_7_name,\n        split_part(administrative_area_path, '','', 8)  AS level_8_name,\n        split_part(administrative_area_path, '','', 9)  AS level_9_name,\n        split_part(administrative_area_path, '','', 10) AS level_10_name\n\n    FROM administrative_area_path\n)\n\nSELECT\n    l.*,\n\n    aa.name AS administrative_area_name,\n\n    aap.administrative_area_path,\n    aap.level AS administrative_area_level,\n\n    -- include location itself in the final full path\n    CASE\n        WHEN aap.administrative_area_path IS NOT NULL\n            THEN aap.administrative_area_path || '','' || l.name\n        ELSE l.name\n    END AS full_path,\n\n    p.level_1_name,\n    p.level_2_name,\n    p.level_3_name,\n    p.level_4_name,\n    p.level_5_name,\n    p.level_6_name,\n    p.level_7_name,\n    p.level_8_name,\n    p.level_9_name,\n    p.level_10_name\n\nFROM app.locations l\n\nLEFT JOIN app.administrative_areas aa\n    ON aa.id = l.administrative_area_id\n\nLEFT JOIN administrative_area_path aap\n    ON aap.id = aa.id\n\nLEFT JOIN pivot p\n    ON p.id = aa.id;"}},"parameter_mappings":[],"display":"table","archived_directly":false,"collection_preview":true,"visualization_settings":{"table.pivot_column":"created_at","table.cell_column":"valid_until"},"parameters":[],"dashboard_id":null}', NULL);    
