(736, 'Dashboard', 12, 1, TIMESTAMP WITH TIME ZONE '2026-07-06 14:27:01.257492+06', U&'{"description":null,"archived":false,"collection_position":null,"tabs":[{"id":23,"dashboard_id":12,"name":"Births","position":0},{"id":24,"dashboard_id":12,"name":"Deaths","position":1}],"enable_embedding":false,"collection_id":8,"name":"Completeness Rates","width":"fixed","embedding_params":null,"cache_ttl":null,"cards":[{"size_x":15,"dashboard_tab_id":23,"series":[],"inline_parameters":[],"action_id":null,"col":0,"id":109,"parameter_mappings":[],"card_id":null,"visualization_settings":{"virtual_card":{"name":null,"display":"text","visualization_settings":{},"archived":false},"text":"The no. of registrations, expressed as a % of the total estimated no. of births occurring. \\n\\nCompleteness Rate (%) = (Number of Registered Births* / Estimated Total Number of Births) \00d7 100\\n\\n\\\\* only registrations where child was under 1 years old at time of registration "},"size_y":6,"dashboard_id":12,"row":0},{"size_x":24,"dashboard_tab_id":23,"series":[],"inline_parameters":[],"action_id":null,"col":0,"id":110,"parameter_mappings":[{"parameter_id":"3e9b2029","card_id":126,"target":["dimension",["field","year",{"base-type":"type/Integer"}],{"stage-number":0}]}],"card_id":126,"visualization_settings":{"click_behavior":{"parameterMapping":{"[\\"dimension\\",[\\"field\\",276,{\\"base-type\\":\\"type/Text\\",\\"join-alias\\":\\"Admin Locations - name\\"}],{\\"stage-number\\":0}]":{"source":{"type":"column","id":"name","name":"name"},"target":{"type":"dimension","id":"[\\"dimension\\",[\\"field\\",276,{\\"base-type\\":\\"type/Text\\",\\"join-alias\\":\\"Admin Locations - name\\"}],{\\"stage-number\\":0}]","dimension":["dimension",["field",276,{"base-type":"type/Text","join-alias":"Admin Locations - name"}],{"stage-number":0}]},"id":"[\\"dimension\\",[\\"field\\",276,{\\"base-type\\":\\"type/Text\\",\\"join-alias\\":\\"Admin Locations - name\\"}],{\\"stage-number\\":0}]"}},"targetId":128,"li