INSERT INTO SYSTEM_LOB_STREAM VALUES(95, 0, '{"description":"Completeness rates per location per year, based on country provided population and crude birth rate statistics","archived":false,"collection_position":1,"source_card_id":null,"table_id":null,"result_metadata":[{"name":"id","database_type":"text","base_type":"type/Text","display_name":"id","semantic_type":"type/PK","field_ref":["field","id",{"base-type":"type/Text"}]},{"name":"name","database_type":"text","base_type":"type/Text","display_name":"name","semantic_type":"type/Name","field_ref":["field","name",{"base-type":"type/Text"}]},{"name":"year","database_type":"int4","base_type":"type/Integer","display_name":"year","field_ref":["field","year",{"base-type":"type/Integer"}],"semantic_type":null},{"name":"crude_birth_rate","database_type":"numeric","base_type":"type/Decimal","display_name":"crude_birth_rate","semantic_type":"type/Share","field_ref":["field","crude_birth_rate",{"base-type":"type/Decimal"}]},{"name":"total_population","database_type":"int4","base_type":"type/Integer","display_name":"total_population","field_ref":["field","total_population",{"base-type":"type/Integer"}],"semantic_type":null},{"name":"estimated_births","database_type":"numeric","base_type":"type/Decimal","display_name":"estimated_births","field_ref":["field","estimated_births",{"base-type":"type/Decimal"}],"semantic_type":null},{"name":"register_count","database_type":"numeric","base_type":"type/Decimal","display_name":"register_count","field_ref":["field","register_count",{"base-type":"type/Decimal"}],"semantic_type":null},{"name":"completeness_rate","database_type":"numeric","base_type":"type/Decimal","display_name":"completeness_rate","semantic_type":"type/Share","field_ref":["field","completeness_rate",{"base-type":"type/Decimal"}]},{"name":"level","database_type":"int4","base_type":"type/Integer","display_name":"level","field_ref":["field","level",{"base-type":"type/Integer"}],"semantic_type":null},{"name":"level_name","database_type":"text","base_type":"type/Text","display_name":"level_name","field_ref":["field","level_name",{"base-type":"type/Text"}],"semantic_type":null}],"card_schema":22,"database_id":2,"enable_embedding":false,"collection_id":9,"query_type":"native","name":"Births completeness rates","type":"model","embedding_params":null,"cache_ttl":null,"dataset_query":{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE\n  levels AS (\n    -- root = 1, children increment\n    SELECT\n      id,\n      parent_id,\n      1 AS LEVEL\n    FROM\n      analytics.administrative_areas\n    WHERE\n      parent_id IS NULL\n    UNION ALL\n    SELECT\n      l.id,\n      l.parent_id,\n      lv.level + 1\n    FROM\n      analytics.administrative_areas l\n      JOIN levels lv ON l.parent_id = lv.id\n  ),\n  -- ancestor/descendant closure: every node is ancestor of itself and all its descendants\n  closure AS (\n    SELECT\n      id AS ancestor_id,\n      id AS descendant_id\n    FROM\n      analytics.administrative_areas\n    UNION ALL\n    SELECT\n      c.ancestor_id,\n      l.id AS descendant_id\n    FROM\n      closure c\n      JOIN analytics.administrative_areas l ON l.parent_id = c.descendant_id\n  ),\n  -- counts at leaf/origin locations by year\n  counts AS (\n    SELECT\n      loc.administrative_area_id AS location_id,\n      EXTRACT(\n        YEAR\n        FROM\n          ea.created_at\n      )::int AS YEAR,\n      COUNT(*) AS cnt\n    FROM\n      analytics.event_actions ea\n      JOIN analytics.locations loc ON loc.id = ea.created_at_location\n    WHERE\n      ea.action_type = ''REGISTER''\n      AND ea.event_type = ''birth''\n      AND ea.created_at IS NOT NULL\n      AND ea.created_at_location IS NOT NULL\n      AND (ea.declaration ->> ''child_dob'')::date > ea.created_at::date - INTERVAL ''365 days''\n    GROUP BY\n      loc.administrative_area_id,\n      YEAR\n  ),\n  -- roll up descendant counts to each ancestor (this is the named query)\n  birth_registrations_per_location AS (\n    SELECT\n      c.ancestor_id AS location_id,\n      cnt.year,\n      SUM(cnt.cnt) AS register_count\n    FROM\n  ', NULL); 
INSERT INTO SYSTEM_LOB_STREAM VALUES(95, 1, '    closure c\n      JOIN counts cnt ON cnt.location_id = c.descendant_id\n    GROUP BY\n      c.ancestor_id,\n      cnt.year\n  )\nSELECT\n  l.id,\n  l.name,\n  s.year,\n  s.crude_birth_rate,\n  s.total_population,\n  (s.total_population / 1000 * s.crude_birth_rate) AS estimated_births,\n  COALESCE(br.register_count, 0) AS register_count,\n  COALESCE(\n    register_count / NULLIF(\n      (s.total_population / 1000 * s.crude_birth_rate),\n      0\n    ) * 100,\n    0\n  ) AS completeness_rate,\n  lv.level,\n  ll.name AS level_name\nFROM\n  analytics.administrative_areas l\n  JOIN analytics.location_statistics s ON s.name = l.name\n  LEFT JOIN birth_registrations_per_location br ON br.location_id = l.id\n  AND br.year = s.year\n  LEFT JOIN levels lv ON lv.id = l.id\n  LEFT JOIN analytics.location_levels ll ON ll.level = lv.level\nORDER BY\n  s.year DESC,\n  register_count DESC;"}},"parameter_mappings":[],"display":"table","archived_directly":false,"collection_preview":true,"visualization_settings":{"graph.x_axis.scale":"ordinal","graph.dimensions":["name"],"table.pivot_column":"crude_birth_rate","table.cell_column":"year","graph.metrics":[]},"parameters":[],"dashboard_id":null}', NULL);              
