"base_type":"type/Text","display_name":"level_2_name","field_ref":["field","level_2_name",{"base-type":"type/Text"}],"semantic_type":"type/City"},{"name":"level_3_name","database_type":"text","base_type":"type/Text","display_name":"level_3_name","field_ref":["field","level_3_name",{"base-type":"type/Text"}],"semantic_type":null},{"name":"level_4_name","database_type":"text","base_type":"type/Text","display_name":"level_4_name","field_ref":["field","level_4_name",{"base-type":"type/Text"}],"semantic_type":null},{"name":"level_5_name","database_type":"text","base_type":"type/Text","display_name":"level_5_name","field_ref":["field","level_5_name",{"base-type":"type/Text"}],"semantic_type":null},{"name":"level_6_name","database_type":"text","base_type":"type/Text","display_name":"level_6_name","field_ref":["field","level_6_name",{"base-type":"type/Text"}],"semantic_type":null},{"name":"level_7_name","database_type":"text","base_type":"type/Text","display_name":"level_7_name","field_ref":["field","level_7_name",{"base-type":"type/Text"}],"semantic_type":null},{"name":"level_8_name","database_type":"text","base_type":"type/Text","display_name":"level_8_name","field_ref":["field","level_8_name",{"base-type":"type/Text"}],"semantic_type":null},{"name":"level_9_name","database_type":"text","base_type":"type/Text","display_name":"level_9_name","field_ref":["field","level_9_name",{"base-type":"type/Text"}],"semantic_type":null},{"name":"level_10_name","database_type":"text","base_type":"type/Text","display_name":"level_10_name","field_ref":["field","level_10_name",{"base-type":"type/Text"}],"semantic_type":null}],"card_schema":22,"database_id":2,"enable_embedding":false,"collection_id":null,"query_type":"native","name":"Locations","type":"model","embedding_params":null,"cache_ttl":null,"dataset_query":{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE\n  administrative_area_path AS (\n    -- roots\n    SELECT\n      aa.id,\n      aa.parent_id,\n      aa.name,\n      aa.name::TEXT AS administrative_area_path,\n      1 AS LEVEL\n    FROM\n      analytics.administrative_areas aa\n    WH', NULL);         
INSERT INTO SYSTEM_LOB_STREAM VALUES(96, 1, 'ERE\n      aa.parent_id IS NULL\n    UNION ALL\n    -- descendants\n    SELECT\n      aa.id,\n      aa.parent_id,\n      aa.name,\n      aap.administrative_area_path || '','' || aa.name,\n      aap.level + 1\n    FROM\n      analytics.administrative_areas aa\n      JOIN administrative_area_path aap ON aa.parent_id = aap.id\n  ),\n  pivot AS (\n    SELECT\n      id,\n      split_part(administrative_area_path, '','', 1) AS level_1_name,\n      split_part(administrative_area_path, '','', 2) AS level_2_name,\n      split_part(administrative_area_path, '','', 3) AS level_3_name,\n      split_part(administrative_area_path, '','', 4) AS level_4_name,\n      split_part(administrative_area_path, '','', 5) AS level_5_name,\n      split_part(administrative_area_path, '','', 6) AS level_6_name,\n      split_part(administrative_area_path, '','', 7) AS level_7_name,\n      split_part(administrative_area_path, '','', 8) AS level_8_name,\n      split_part(administrative_area_path, '','', 9) AS level_9_name,\n      split_part(administrative_area_path, '','', 10) AS level_10_name\n    FROM\n      administrative_area_path\n  )\nSELECT\n  l.id::TEXT AS id,\n  l.name,\n  l.location_type,\n  l.administrative_area_id,\n  aa.name AS administrative_area_name,\n  aap.administrative_area_path,\n  aap.level AS administrative_area_level,\n  -- include location itself in the final full path\n  CASE\n    WHEN aap.administrative_area_path IS NOT NULL THEN aap.administrative_area_path || '','' || l.name\n    ELSE l.name\n  END AS full_path,\n  p.level_1_name,\n  p.level_2_name,\n  p.level_3_name,\n  p.level_4_name,\n  p.level_5_name,\n  p.level_6_name,\n  p.level_7_name,\n  p.level_8_name,\n  p.level_9_name,\n  p.level_10_name\nFROM\n  analytics.locations l\n  LEFT JOIN analytics.administrative_areas aa ON aa.id = l.administrative_area_id\n  LEFT JOIN administrative_area_path aap ON aap.id = aa.id\n  LEFT JOIN pivot p ON p.id = aa.id;"}},"parameter_mappings":[],"display":"table","archived_directly":false,"collection_preview":true,"visualization_settings":{"table.pivot_column":"created_at","table.cell_column":"valid_until"},"parameters":[],"dashboard_id":null}', NULL);     
