(X'b67148c14026d7163826a9327c79a9f24e55a5f914ce7d7de634d2f1046c3c11', 13, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE location_path AS (\n  SELECT\n    id,\n    parent_id,\n    name,\n    name::text AS path\n  FROM analytics.locations\n  WHERE parent_id IS NULL\n\n  UNION ALL\n\n  SELECT\n    l.id,\n    l.parent_id,\n    l.name,\n    lp.path || '' -> '' || l.name\n  FROM analytics.locations l\n  JOIN location_path lp ON l.parent_id = lp.id\n)\nSELECT l.*, lp.path AS full_path\nFROM analytics.locations l\nJOIN location_path lp ON l.id = lp.id;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}'),
