(X'dec043801db4d9b4691cc4770f42a394b2649dc8808917f8193c99527db87109', 2, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"type":"native","middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"process-viz-settings?":false,"userland-query?":true},"cache-strategy":null,"native":{"template-tags":{},"query":"WITH RECURSIVE location_path AS (\n  SELECT id, parent_id, name, name::text AS path, 1 AS level\n  FROM analytics.locations\n  WHERE parent_id IS NULL\n  UNION ALL\n  SELECT l.id, l.parent_id, l.name, lp.path || '','' || l.name, lp.level + 1\n  FROM analytics.locations l\n  JOIN location_path lp ON l.parent_id = lp.id\n)\nSELECT\n  l.*,\n  lp.path   AS full_path,\n  lp.level,\n  ll.id     AS level_id\nFROM analytics.locations l\nJOIN location_path lp ON l.id = lp.id\nLEFT JOIN analytics.location_levels ll\n  ON ll.level = lp.level"},"viz-settings":{"table.pivot_column":"created_at","table.cell_column":"valid_until"},"database":2}');              
