(X'2c37adfda8f7628bae85882e1f7d6192c7184a9a77cfeca02771df6a3f6e6465', 12, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE location_path AS (\n  SELECT\n    l.id,\n    l.parent_id,\n    l.name,\n    l.name::text AS path,\n    1 AS level,\n    jsonb_build_object(ll.id::text, l.id) AS level_map\n  FROM analytics.locations l\n  JOIN analytics.location_levels ll ON ll.level = 1\n  WHERE l.parent_id IS NULL\n\n  UNION ALL\n\n  SELECT\n    l.id,\n    l.parent_id,\n    l.name,\n    lp.path || '','' || l.name,\n    lp.level + 1 AS level,\n    lp.level_map\n      || jsonb_build_object(\n           (SELECT ll2.id::text\n              FROM analytics.location_levels ll2\n             WHERE ll2.level = lp.level + 1),\n           l.id\n         ) AS level_map\n  FROM analytics.locations l\n  JOIN location_path lp ON l.parent_id = lp.id\n)\nSELECT\n  l.*,\n  lp.path        AS full_path,\n  lp.level,\n  ll.id          AS level_id,\n  lp.level_map   -- {<level_id>: <ancestor_location_id>, ...}\nFROM analytics.locations l\nJOIN location_path lp ON l.id = lp.id\nLEFT JOIN analytics.location_levels ll ON ll.level = lp.level;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}'),
(X'e2f143da2d0378c80e89fb903c3c2aed6aa8857208c34155cef4c0dbf58b0ff2', 13, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE location_path AS (\n  SELECT id, parent_id, name, name::text AS path, 1 AS level\n  FROM analytics.locations\n  WHERE parent_id IS NULL\n  UNION ALL\n  SELECT l.id, l.parent_id, l.name, lp.path || '','' || l.name, lp.level + 1\n  FROM analytics.locations l\n  JOIN location_path lp ON l.parent_id = lp.id\n)\nSELECT\n  l.*,\n  lp.path   AS full_path,\n  lp.level,\n  ll.id     AS level_id\nFROM analytics.locations l\nJOIN location_path lp ON l.id = lp.id\nLEFT JOIN analytics.location_levels ll\n  ON ll.level = lp.level;\n"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}'),
