(X'bcf6f58a0a4b2a833bda83a6cd887812a7b28cbc272baaec91035ec053211c2b', 17, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE location_hierarchy AS (\n    SELECT id, parent_id, id AS root_id\n    FROM analytics.locations\n    UNION ALL\n    SELECT l.id, l.parent_id, h.root_id\n    FROM analytics.locations l\n    JOIN location_hierarchy h ON l.parent_id = h.id\n),\ncounts AS (\n    SELECT l.id, COUNT(*) AS cnt\n    FROM analytics.locations l\n    JOIN analytics.event_actions ea ON ea.action_type = ''REGISTER'' AND ea.created_at IS NOT NULL\n    -- assuming event_actions table has location_id (missing from your schema!)\n    AND ea.location_id = l.id\n    GROUP BY l.id\n)\nSELECT h.root_id AS location_id, COALESCE(SUM(c.cnt), 0) AS register_count\nFROM location_hierarchy h\nLEFT JOIN counts c ON h.id = c.id\nGROUP BY h.root_id;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}'),
(X'4e51eee96b5e1ea8fde5edff38bdea9d87206624e9a49145523732273c39aecb', 13, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE location_hierarchy AS (\n    SELECT id, parent_id, id AS root_id\n    FROM analytics.locations\n    UNION ALL\n    SELECT l.id, l.parent_id, h.root_id\n    FROM analytics.locations l\n    JOIN location_hierarchy h ON l.parent_id = h.id\n),\ncounts AS (\n    SELECT l.id, COUNT(*) AS cnt\n    FROM analytics.locations l\n    JOIN analytics.event_actions ea ON ea.action_type = ''REGISTER'' AND ea.created_at IS NOT NULL\n    -- assuming event_actions table has location_id (missing from your schema!)\n    AND ea.id = l.id\n    GROUP BY l.id\n)\nSELECT h.root_id AS location_id, COALESCE(SUM(c.cnt), 0) AS register_count\nFROM location_hierarchy h\nLEFT JOIN counts c ON h.id = c.id\nGROUP BY h.root_id;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');       
INSERT INTO "PUBLIC"."QUERY" VALUES
(X'bfcb2e33211dcc71dad21ec32a184855c6c91d1d20c34ca55ff31c0484cb0898', 11, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE location_hierarchy AS (\n    SELECT id, parent_id, id AS root_id\n    FROM analytics.locations\n    UNION ALL\n    SELECT l.id, l.parent_id, h.root_id\n    FROM analytics.locations l\n    JOIN location_hierarchy h ON l.parent_id = h.id\n),\ncounts AS (\n    SELECT l.id, COUNT(*) AS cnt\n    FROM analytics.locations l\n    JOIN analytics.event_actions ea ON ea.action_type = ''REGISTER'' AND ea.created_at IS NOT NULL\n    -- assuming event_actions table has location_id (missing from your schema!)\n    AND ea.created_at = l.id\n    GROUP BY l.id\n)\nSELECT h.root_id AS location_id, COALESCE(SUM(c.cnt), 0) AS register_count\nFROM location_hierarchy h\nLEFT JOIN counts c ON h.id = c.id\nGROUP BY h.root_id;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}'),
(X'6e63b8f8cef4aa8733e8a4ec1b6a671f99b23a9d62c5cd9450eedcc0ef39abc1', 10, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE location_hierarchy AS (\n    SELECT id, parent_id, id AS root_id\n    FROM analytics.locations\n    UNION ALL\n    SELECT l.id, l.parent_id, h.root_id\n    FROM analytics.locations l\n    JOIN location_hierarchy h ON l.parent_id = h.id\n),\ncounts AS (\n    SELECT l.id, COUNT(*) AS cnt\n    FROM analytics.locations l\n    JOIN analytics.event_actions ea ON ea.action_type = ''REGISTER'' AND ea.created_at IS NOT NULL\n    -- assuming event_actions table has location_id (missing from your schema!)\n    AND ea.created_at_location = l.id\n    GROUP BY l.id\n)\nSELECT h.root_id AS location_id, COALESCE(SUM(c.cnt), 0) AS register_count\nFROM location_hierarchy h\nLEFT JOIN counts c ON h.id = c.id\nGROUP BY h.root_id;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}'),
(X'8a523d630a9160f4e331d00f409dfa6308613815e312ab67018073c1f16afd4a', 68, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE location_hierarchy AS (\n    SELECT id, parent_id, id AS root_id\n    FROM analytics.locations\n    UNION ALL\n    SELECT l.id, l.parent_id, h.root_id\n    FROM analytics.locations l\n    JOIN location_hierarchy h ON l.parent_id = h.id\n),\ncounts AS (\n    SELECT l.id, COUNT(*) AS cnt\n    FROM analytics.locations l\n    JOIN analytics.event_actions ea \n      ON ea.action_type = ''REGISTER''\n     AND ea.event_type = ''birth''\n     AND ea.created_at IS NOT NULL\n     AND ea.created_at_location = l.id\n    GROUP BY l.id\n)\nSELECT h.root_id AS location_id,\n       COALESCE(SUM(c.cnt), 0) AS register_count\nFROM location_hierarchy h\nLEFT JOIN counts c ON h.id = c.id\nGROUP BY h.root_id\nORDER BY register_count DESC;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}'),
(X'688017ddd508537aa4ed681e3c79b5e7e439e3444096147667a1467aeee9533f', 20, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE location_hierarchy AS (\n    SELECT id, parent_id, id AS root_id\n    FROM analytics.locations\n    UNION ALL\n    SELECT l.id, l.parent_id, h.root_id\n    FROM analytics.locations l\n    JOIN location_hierarchy h ON l.parent_id = h.id\n),\ncounts AS (\n    SELECT l.id, COUNT(*) AS cnt\n    FROM analytics.locations l\n    JOIN analytics.event_actions ea \n      ON ea.action_type = ''REGISTER''\n     AND ea.event_type = ''birth''\n     AND ea.created_at IS NOT NULL\n     AND ea.created_at_location = l.id\n    GROUP BY l.id\n)\nSELECT root.id   AS location_id,\n       root.name AS location_name,\n       COALESCE(SUM(c.cnt), 0) AS register_count\nFROM location_hierarchy h\nJOIN analytics.locations root ON root.id = h.root_id\nLEFT JOIN counts c ON h.id = c.id\nGROUP BY root.id, root.name\nORDER BY register_count DESC;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}'),
(X'f27e682d995f4210602e49e18991d3a706a041bb64d2ebceabd408cd7dfee073', 10, '{"database":2,"type":"native","native":{"template-tags":{},"query":"\nSELECT \n  l.id, \n  l.name, \n  s.year, \n  s.crude_birth_rate, \n  s.total_population, \n  (s.total_population / 1000 * s.crude_birth_rate) estimated_births\n\nFROM analytics.locations l \nLEFT JOIN analytics.location_statistics s on s.name = l.name"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');       
INSERT INTO "PUBLIC"."QUERY" VALUES
(X'eac190d27a91e2455392136af9e30cc72963f5b7542eaa741e7d0db40320f748', 11, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE location_hierarchy AS (\n    SELECT id, parent_id, id AS root_id\n    FROM analytics.locations\n    UNION ALL\n    SELECT l.id, l.parent_id, h.root_id\n    FROM analytics.locations l\n    JOIN location_hierarchy h ON l.parent_id = h.id\n),\ncounts AS (\n    SELECT l.id, COUNT(*) AS cnt\n    FROM analytics.locations l\n    JOIN analytics.event_actions ea \n      ON ea.action_type = ''REGISTER''\n     AND ea.event_type = ''birth''\n     AND ea.created_at IS NOT NULL\n     AND ea.created_at_location = l.id\n    GROUP BY l.id\n),\nbirth_registrations_per_location AS (\n    SELECT root.id   AS location_id,\n           root.name AS location_name,\n           COALESCE(SUM(c.cnt), 0) AS register_count\n    FROM location_hierarchy h\n    JOIN analytics.locations root ON root.id = h.root_id\n    LEFT JOIN counts c ON h.id = c.id\n    GROUP BY root.id, root.name\n)\nSELECT \n    l.id,\n    l.name,\n    s.year,\n    s.crude_birth_rate,\n    s.total_population,\n    (s.total_population / 1000 * s.crude_birth_rate) AS estimated_births,\n    br.register_count\nFROM analytics.locations l\nLEFT JOIN analytics.location_statistics s ON s.name = l.name\nLEFT JOIN birth_registrations_per_location br ON br.location_id = l.id\nORDER BY br.register_count DESC NULLS LAST;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}'),
(X'9f937a80f981692c2926dbf28a18a405cfc3fb7082ce27e0f593cb3f466e9af5', 20, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE location_hierarchy AS (\n    SELECT id, parent_id, id AS root_id\n    FROM analytics.locations\n    UNION ALL\n    SELECT l.id, l.parent_id, h.root_id\n    FROM analytics.locations l\n    JOIN location_hierarchy h ON l.parent_id = h.id\n),\ncounts AS (\n    SELECT l.id,\n           EXTRACT(YEAR FROM ea.created_at)::int AS year,\n           COUNT(*) AS cnt\n    FROM analytics.locations l\n    JOIN analytics.event_actions ea \n      ON ea.action_type = ''REGISTER''\n     AND ea.event_type = ''birth''\n     AND ea.created_at IS NOT NULL\n     AND ea.created_at_location = l.id\n    GROUP BY l.id, year\n),\nbirth_registrations_per_location AS (\n    SELECT root.id   AS location_id,\n           root.name AS location_name,\n           c.year,\n           COALESCE(SUM(c.cnt), 0) AS register_count\n    FROM location_hierarchy h\n    JOIN analytics.locations root ON root.id = h.root_id\n    LEFT JOIN counts c ON h.id = c.id\n    GROUP BY root.id, root.name, c.year\n)\nSELECT \n    l.id,\n    l.name,\n    s.year,\n    s.crude_birth_rate,\n    s.total_population,\n    (s.total_population / 1000 * s.crude_birth_rate) AS estimated_births,\n    br.register_count\nFROM analytics.locations l\nLEFT JOIN analytics.location_statistics s \n       ON s.name = l.name\nLEFT JOIN birth_registrations_per_location br \n       ON br.location_id = l.id AND br.year = s.year\nORDER BY br.year DESC, br.register_count DESC NULLS LAST;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}'),
(X'38322dbe0e4f6766ae7c9f6ca9b083f3ddf131d71fc51b19c7e2af1e74400c85', 13, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE location_hierarchy AS (\n    SELECT id, parent_id, id AS root_id\n    FROM analytics.locations\n    UNION ALL\n    SELECT l.id, l.parent_id, h.root_id\n    FROM analytics.locations l\n    JOIN location_hierarchy h ON l.parent_id = h.id\n),\ncounts AS (\n    SELECT l.id,\n           EXTRACT(YEAR FROM ea.created_at)::int AS year,\n           COUNT(*) AS cnt\n    FROM analytics.locations l\n    JOIN analytics.event_actions ea \n      ON ea.action_type = ''REGISTER''\n     AND ea.event_type = ''birth''\n     AND ea.created_at IS NOT NULL\n     AND ea.created_at_location = l.id\n    GROUP BY l.id, year\n),\nbirth_registrations_per_location AS (\n    SELECT root.id   AS location_id,\n           root.name AS location_name,\n           c.year,\n           COALESCE(SUM(c.cnt), 0) AS register_count\n    FROM location_hierarchy h\n    JOIN analytics.locations root ON root.id = h.root_id\n    LEFT JOIN counts c ON h.id = c.id\n    GROUP BY root.id, root.name, c.year\n)\nSELECT \n    l.id,\n    l.name,\n    s.year,\n    s.crude_birth_rate,\n    s.total_population,\n    (s.total_population / 1000 * s.crude_birth_rate) AS estimated_births,\n    COALESCE(br.register_count, 0) AS register_count\nFROM analytics.locations l\nJOIN analytics.location_statistics s \n       ON s.name = l.name\nLEFT JOIN birth_registrations_per_location br \n       ON br.location_id = l.id AND br.year = s.year\nORDER BY s.year DESC, register_count DESC;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');     
INSERT INTO "PUBLIC"."QUERY" VALUES
(X'3e1b469ec463df52beabed7376c66057417b1982cc8637c417a0877b6007630b', 17, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE location_hierarchy AS (\n    SELECT id, parent_id, id AS root_id\n    FROM analytics.locations\n    UNION ALL\n    SELECT l.id, l.parent_id, h.root_id\n    FROM analytics.locations l\n    JOIN location_hierarchy h ON l.parent_id = h.id\n),\ncounts AS (\n    SELECT l.id,\n           EXTRACT(YEAR FROM ea.created_at)::int AS year,\n           COUNT(*) AS cnt\n    FROM analytics.locations l\n    JOIN analytics.event_actions ea \n      ON ea.action_type = ''REGISTER''\n     AND ea.event_type = ''birth''\n     AND ea.created_at IS NOT NULL\n     AND ea.created_at_location = l.id\n    GROUP BY l.id, year\n),\nbirth_registrations_per_location AS (\n    SELECT root.id   AS location_id,\n           root.name AS location_name,\n           c.year,\n           COALESCE(SUM(c.cnt), 0) AS register_count\n    FROM location_hierarchy h\n    JOIN analytics.locations root ON root.id = h.root_id\n    LEFT JOIN counts c ON h.id = c.id\n    GROUP BY root.id, root.name, c.year\n)\nSELECT \n    l.id,\n    l.name,\n    s.year,\n    s.crude_birth_rate,\n    s.total_population,\n    (s.total_population / 1000 * s.crude_birth_rate) AS estimated_births,\n\tCOALESCE(br.register_count, 0) AS register_count,\n\t(register_count / estimated_births) * 100\n    \nFROM analytics.locations l\nJOIN analytics.location_statistics s \n       ON s.name = l.name\nLEFT JOIN birth_registrations_per_location br \n       ON br.location_id = l.id AND br.year = s.year\nORDER BY s.year DESC, register_count DESC;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}'),
(X'ef43ec2f4c9c960c86ed5bb3604c775936848a69b6ba460640965b0c112b5ad2', 7, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE location_hierarchy AS (\n    SELECT id, parent_id, id AS root_id\n    FROM analytics.locations\n    UNION ALL\n    SELECT l.id, l.parent_id, h.root_id\n    FROM analytics.locations l\n    JOIN location_hierarchy h ON l.parent_id = h.id\n),\ncounts AS (\n    SELECT l.id,\n           EXTRACT(YEAR FROM ea.created_at)::int AS year,\n           COUNT(*) AS cnt\n    FROM analytics.locations l\n    JOIN analytics.event_actions ea \n      ON ea.action_type = ''REGISTER''\n     AND ea.event_type = ''birth''\n     AND ea.created_at IS NOT NULL\n     AND ea.created_at_location = l.id\n    GROUP BY l.id, year\n),\nbirth_registrations_per_location AS (\n    SELECT root.id   AS location_id,\n           root.name AS location_name,\n           c.year,\n           COALESCE(SUM(c.cnt), 0) AS register_count\n    FROM location_hierarchy h\n    JOIN analytics.locations root ON root.id = h.root_id\n    LEFT JOIN counts c ON h.id = c.id\n    GROUP BY root.id, root.name, c.year\n)\nSELECT \n    l.id,\n    l.name,\n    s.year,\n    s.crude_birth_rate,\n    s.total_population,\n    (s.total_population / 1000 * s.crude_birth_rate) AS estimated_births,\n\tCOALESCE(br.register_count, 0) AS register_count,\n\t((register_count / estimated_births) * 100) completeness_rate\nFROM analytics.locations l\nJOIN analytics.location_statistics s \n       ON s.name = l.name\nLEFT JOIN birth_registrations_per_location br \n       ON br.location_id = l.id AND br.year = s.year\nORDER BY s.year DESC, register_count DESC;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}'),
(X'7500ac8ea99c84da745fe5b3b50c25e17e5f085f61af74d16786e427d7846a9e', 9, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE location_hierarchy AS (\n    SELECT id, parent_id, id AS root_id\n    FROM analytics.locations\n    UNION ALL\n    SELECT l.id, l.parent_id, h.root_id\n    FROM analytics.locations l\n    JOIN location_hierarchy h ON l.parent_id = h.id\n),\ncounts AS (\n    SELECT l.id,\n           EXTRACT(YEAR FROM ea.created_at)::int AS year,\n           COUNT(*) AS cnt\n    FROM analytics.locations l\n    JOIN analytics.event_actions ea \n      ON ea.action_type = ''REGISTER''\n     AND ea.event_type = ''birth''\n     AND ea.created_at IS NOT NULL\n     AND ea.created_at_location = l.id\n    GROUP BY l.id, year\n),\nbirth_registrations_per_location AS (\n    SELECT root.id   AS location_id,\n           root.name AS location_name,\n           c.year,\n           COALESCE(SUM(c.cnt), 0) AS register_count\n    FROM location_hierarchy h\n    JOIN analytics.locations root ON root.id = h.root_id\n    LEFT JOIN counts c ON h.id = c.id\n    GROUP BY root.id, root.name, c.year\n)\nSELECT \n    l.id,\n    l.name,\n    s.year,\n    s.crude_birth_rate,\n    s.total_population,\n    (s.total_population / 1000 * s.crude_birth_rate) AS estimated_births,\n\tCOALESCE(br.register_count, 0) AS register_count,\n\t((register_count / estimated_births) * 100) AS completeness_rate\nFROM analytics.locations l\nJOIN analytics.location_statistics s \n       ON s.name = l.name\nLEFT JOIN birth_registrations_per_location br \n       ON br.location_id = l.id AND br.year = s.year\nORDER BY s.year DESC, register_count DESC;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');              
INSERT INTO "PUBLIC"."QUERY" VALUES
(X'a2ed158cbce6d2d8b3b2bc483bdfcfdab806b31ef3beca4628fee35e9594cc88', 22, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE location_hierarchy AS (\n    SELECT id, parent_id, id AS root_id\n    FROM analytics.locations\n    UNION ALL\n    SELECT l.id, l.parent_id, h.root_id\n    FROM analytics.locations l\n    JOIN location_hierarchy h ON l.parent_id = h.id\n),\ncounts AS (\n    SELECT l.id,\n           EXTRACT(YEAR FROM ea.created_at)::int AS year,\n           COUNT(*) AS cnt\n    FROM analytics.locations l\n    JOIN analytics.event_actions ea \n      ON ea.action_type = ''REGISTER''\n     AND ea.event_type = ''birth''\n     AND ea.created_at IS NOT NULL\n     AND ea.created_at_location = l.id\n    GROUP BY l.id, year\n),\nbirth_registrations_per_location AS (\n    SELECT root.id   AS location_id,\n           root.name AS location_name,\n           c.year,\n           COALESCE(SUM(c.cnt), 0) AS register_count\n    FROM location_hierarchy h\n    JOIN analytics.locations root ON root.id = h.root_id\n    LEFT JOIN counts c ON h.id = c.id\n    GROUP BY root.id, root.name, c.year\n)\nSELECT \n    l.id,\n    l.name,\n    s.year,\n    s.crude_birth_rate,\n    s.total_population,\n    (s.total_population / 1000 * s.crude_birth_rate) AS estimated_births,\n\tCOALESCE(br.register_count, 0) AS register_count,\n\t((register_count / (s.total_population / 1000 * s.crude_birth_rate)) * 100) AS completeness_rate\nFROM analytics.locations l\nJOIN analytics.location_statistics s \n       ON s.name = l.name\nLEFT JOIN birth_registrations_per_location br \n       ON br.location_id = l.id AND br.year = s.year\nORDER BY s.year DESC, register_count DESC;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}'),
(X'30a9a124f46b13e1354d422bda1f4ad08fb1ee7e676ad2ce1574321c7a789536', 27, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"type":"native","middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"native":{"template-tags":{},"query":"WITH RECURSIVE location_hierarchy AS (\n    SELECT id, parent_id, id AS root_id\n    FROM analytics.locations\n    UNION ALL\n    SELECT l.id, l.parent_id, h.root_id\n    FROM analytics.locations l\n    JOIN location_hierarchy h ON l.parent_id = h.id\n),\ncounts AS (\n    SELECT l.id,\n           EXTRACT(YEAR FROM ea.created_at)::int AS year,\n           COUNT(*) AS cnt\n    FROM analytics.locations l\n    JOIN analytics.event_actions ea \n      ON ea.action_type = ''REGISTER''\n     AND ea.event_type = ''birth''\n     AND ea.created_at IS NOT NULL\n     AND ea.created_at_location = l.id\n    GROUP BY l.id, year\n),\nbirth_registrations_per_location AS (\n    SELECT root.id   AS location_id,\n           root.name AS location_name,\n           c.year,\n           COALESCE(SUM(c.cnt), 0) AS register_count\n    FROM location_hierarchy h\n    JOIN analytics.locations root ON root.id = h.root_id\n    LEFT JOIN counts c ON h.id = c.id\n    GROUP BY root.id, root.name, c.year\n)\nSELECT \n    l.id,\n    l.name,\n    s.year,\n    s.crude_birth_rate,\n    s.total_population,\n    (s.total_population / 1000 * s.crude_birth_rate) AS estimated_births,\n\tCOALESCE(br.register_count, 0) AS register_count,\n\t((register_count / (s.total_population / 1000 * s.crude_birth_rate)) * 100) AS completeness_rate\nFROM analytics.locations l\nJOIN analytics.location_statistics s \n       ON s.name = l.name\nLEFT JOIN birth_registrations_per_location br \n       ON br.location_id = l.id AND br.year = s.year\nORDER BY s.year DESC, register_count DESC;"},"viz-settings":{"table.pivot_column":"register_count","table.cell_column":"year"},"database":2}'),
