INSERT INTO "PUBLIC"."QUERY" VALUES
(X'f0edb64ede93d3ad879fa1f7574ba8568d6d5d601877b02e856e239d0b2a3c97', 17, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE location_hierarchy AS (\n    SELECT id, parent_id, id AS root_id, 0 AS level\n    FROM analytics.locations\n    UNION ALL\n    SELECT l.id, l.parent_id, h.root_id, h.level + 1\n    FROM analytics.locations l\n    JOIN location_hierarchy h ON l.parent_id = h.id\n),\ncounts AS (\n    SELECT l.id,\n           EXTRACT(YEAR FROM ea.created_at)::int AS year,\n           COUNT(*) AS cnt\n    FROM analytics.locations l\n    JOIN analytics.event_actions ea \n      ON ea.action_type = ''REGISTER''\n     AND ea.event_type = ''birth''\n     AND ea.created_at IS NOT NULL\n     AND ea.created_at_location = l.id\n    GROUP BY l.id, year\n),\nbirth_registrations_per_location AS (\n    SELECT root.id   AS location_id,\n           root.name AS location_name,\n           c.year,\n           MIN(h.level) AS level,  -- minimum level from hierarchy\n           COALESCE(SUM(c.cnt), 0) AS register_count\n    FROM location_hierarchy h\n    JOIN analytics.locations root ON root.id = h.root_id\n    LEFT JOIN counts c ON h.id = c.id\n    GROUP BY root.id, root.name, c.year\n)\nSELECT \n    l.id,\n    l.name,\n    s.year,\n    s.crude_birth_rate,\n    s.total_population,\n    (s.total_population / 1000 * s.crude_birth_rate) AS estimated_births,\n    COALESCE(br.register_count, 0) AS register_count,\n    br.level\nFROM analytics.locations l\nJOIN analytics.location_statistics s \n       ON s.name = l.name\nLEFT JOIN birth_registrations_per_location br \n       ON br.location_id = l.id AND br.year = s.year\nORDER BY s.year DESC, register_count DESC;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}'),
(X'026bc17afad102edd0543092e74145574326c8d20c312ac6a51ded783087d92c', 20, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE location_hierarchy AS (\n    SELECT id, parent_id, id AS root_id, 1 AS level\n    FROM analytics.locations\n    UNION ALL\n    SELECT l.id, l.parent_id, h.root_id, h.level + 1\n    FROM analytics.locations l\n    JOIN location_hierarchy h ON l.parent_id = h.id\n),\ncounts AS (\n    SELECT l.id,\n           EXTRACT(YEAR FROM ea.created_at)::int AS year,\n           COUNT(*) AS cnt\n    FROM analytics.locations l\n    JOIN analytics.event_actions ea \n      ON ea.action_type = ''REGISTER''\n     AND ea.event_type = ''birth''\n     AND ea.created_at IS NOT NULL\n     AND ea.created_at_location = l.id\n    GROUP BY l.id, year\n),\nbirth_registrations_per_location AS (\n    SELECT root.id   AS location_id,\n           root.name AS location_name,\n           c.year,\n           MIN(h.level) AS level,\n           COALESCE(SUM(c.cnt), 0) AS register_count\n    FROM location_hierarchy h\n    JOIN analytics.locations root ON root.id = h.root_id\n    LEFT JOIN counts c ON h.id = c.id\n    GROUP BY root.id, root.name, c.year\n)\nSELECT \n    l.id,\n    l.name,\n    s.year,\n    s.crude_birth_rate,\n    s.total_population,\n    (s.total_population / 1000 * s.crude_birth_rate) AS estimated_births,\n    COALESCE(br.register_count, 0) AS register_count,\n    br.level\nFROM analytics.locations l\nJOIN analytics.location_statistics s \n       ON s.name = l.name\nLEFT JOIN birth_registrations_per_location br \n       ON br.location_id = l.id AND br.year = s.year\nORDER BY s.year DESC, register_count DESC;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}'),
(X'5ce967a56c1ba5358b1270f814f7672ef2196b6d0f45f8ee776a4b4767b0e690', 9, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE location_hierarchy AS (\n    SELECT id, parent_id, id AS root_id, 1 AS level\n    FROM analytics.locations\n    WHERE parent_id IS NULL\n    UNION ALL\n    SELECT l.id, l.parent_id, h.root_id, h.level + 1\n    FROM analytics.locations l\n    JOIN location_hierarchy h ON l.parent_id = h.id\n),\ncounts AS (\n    SELECT l.id,\n           EXTRACT(YEAR FROM ea.created_at)::int AS year,\n           COUNT(*) AS cnt\n    FROM analytics.locations l\n    JOIN analytics.event_actions ea \n      ON ea.action_type = ''REGISTER''\n     AND ea.event_type = ''birth''\n     AND ea.created_at IS NOT NULL\n     AND ea.created_at_location = l.id\n    GROUP BY l.id, year\n),\nbirth_registrations_per_location AS (\n    SELECT root.id   AS location_id,\n           root.name AS location_name,\n           c.year,\n           MIN(h.level) AS level,\n           COALESCE(SUM(c.cnt), 0) AS register_count\n    FROM location_hierarchy h\n    JOIN analytics.locations root ON root.id = h.root_id\n    LEFT JOIN counts c ON h.id = c.id\n    GROUP BY root.id, root.name, c.year\n)\nSELECT \n    l.id,\n    l.name,\n    s.year,\n    s.crude_birth_rate,\n    s.total_population,\n    (s.total_population / 1000 * s.crude_birth_rate) AS estimated_births,\n    COALESCE(br.register_count, 0) AS register_count,\n    br.level\nFROM analytics.locations l\nJOIN analytics.location_statistics s \n       ON s.name = l.name\nLEFT JOIN birth_registrations_per_location br \n       ON br.location_id = l.id AND br.year = s.year\nORDER BY s.year DESC, register_count DESC;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');   
