(X'25d3d043b5a4b61347358de1705f878ba7c869ec75705d3d8147c885749c0d63', 10, '{"database":2,"type":"native","native":{"template-tags":{},"query":"SELECT * FROM analytics.event_actions WHERE action_type = ''REGISTER'' and event_type = ''birth''"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}'),
(X'2ff01c18d727d3cc07780b2eb6645e78115049e17bc761a4a020355ec38478fb', 10, '{"database":2,"type":"native","native":{"template-tags":{},"query":"SELECT *\nFROM analytics.event_actions\nWHERE action_type = ''REGISTER''\n  AND event_type = ''birth''\n  AND (created_at::date - (declaration->>''child_dob'')::date) < 365;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}'),
(X'e15821b95a6a4e39463139151df0f5ba9ea7e805bd23f6b8685a303ad9c93f17', 10, '{"database":2,"type":"native","native":{"template-tags":{},"query":"SELECT COUNT(*)\nFROM analytics.event_actions\nWHERE action_type = ''REGISTER''\n  AND event_type = ''birth''\n  AND (created_at::date - (declaration->>''child_dob'')::date) < 365;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}'),
(X'ff014e780bf93ad6cd3375eff79e1441abfb1b0edfea41eb37eebc0cff22312a', 8, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH birth_rate AS (\n  SELECT \n    AVG(crude_birth_rate) AS country_birth_rate\n  FROM \n    analytics.location_statistics\n  WHERE \n    year = 2025\n),\nregistered_births AS (\n  SELECT \n    COUNT(*) AS registered_count\n  FROM \n    analytics.event_actions\n  WHERE \n    action_type = ''REGISTER''\n    AND event_type = ''birth''\n    AND (created_at::date - (declaration->>''child_dob'')::date) < 365\n)\nSELECT \n  (r.registered_count / b.country_birth_rate) * 100 AS registered_birth_percentage\nFROM \n  registered_births r, \n  birth_rate b;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}'),
