(X'0193ba17eaeed329664b11dde91d7397823eaa49fa6e58b5eba85aa3557e1f4d', 11, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH top_level_locations AS (\n  SELECT name\n  FROM analytics.locations\n  WHERE parent_id IS NULL\n),\npopulation_sum AS (\n  SELECT \n    SUM(population) AS total_population\n  FROM \n    analytics.location_statistics s\n  JOIN \n    top_level_locations l ON s.location_name = l.name\n  WHERE \n    s.year = 2025\n),\nbirth_rate AS (\n  SELECT \n    AVG(crude_birth_rate) AS country_birth_rate\n  FROM \n    analytics.location_statistics\n  WHERE \n    year = 2025\n),\nregistered_births AS (\n  SELECT \n    COUNT(*) AS registered_count\n  FROM \n    analytics.event_actions\n  WHERE \n    action_type = ''REGISTER''\n    AND event_type = ''birth''\n    AND (created_at::date - (declaration->>''child_dob'')::date) < 365\n)\nSELECT \n  (r.registered_count / b.country_birth_rate) * 100 AS registered_birth_percentage,\n  p.total_population\nFROM \n  registered_births r,\n  birth_rate b,\n  population_sum p;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');      
