(X'd2b6fcc516b70ede87bb4b0ba0ec61786a85dcd23f7ec5220000f1e7b02f9250', 7, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH top_level_locations AS (\n  SELECT name\n  FROM analytics.locations\n  WHERE parent_id IS NULL\n),\npopulation_sum AS (\n  SELECT \n    SUM(total_population) AS total_population\n  FROM \n    analytics.location_statistics s\n  JOIN \n    top_level_locations l ON s.name = l.name\n  WHERE \n    s.year = 2025\n),\nbirth_rate AS (\n  SELECT \n    AVG(crude_birth_rate) AS country_birth_rate\n  FROM \n    analytics.location_statistics\n  WHERE \n    year = 2025\n),\nregistered_births AS (\n  SELECT \n    COUNT(*) AS registered_count\n  FROM \n    analytics.event_actions\n  WHERE \n    action_type = ''REGISTER''\n    AND event_type = ''birth''\n    AND (created_at::date - (declaration->>''child_dob'')::date) < 365\n)\nSELECT \n  r.registered_count / (p / 1000 * b.country_birth_rate) AS registered_birth_percentage\nFROM \n  registered_births r,\n  birth_rate b,\n  population_sum p;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}'),
(X'8c943ac2d4fe6c0f405a7ace75c3ce79f62d5c0976ac78355b72480180072a37', 7, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH top_level_locations AS (\n  SELECT name\n  FROM analytics.locations\n  WHERE parent_id IS NULL\n),\npopulation_sum AS (\n  SELECT \n    SUM(total_population) AS total_population\n  FROM \n    analytics.location_statistics s\n  JOIN \n    top_level_locations l ON s.name = l.name\n  WHERE \n    s.year = 2025\n),\nbirth_rate AS (\n  SELECT \n    AVG(crude_birth_rate) AS country_birth_rate\n  FROM \n    analytics.location_statistics\n  WHERE \n    year = 2025\n),\nregistered_births AS (\n  SELECT \n    COUNT(*) AS registered_count\n  FROM \n    analytics.event_actions\n  WHERE \n    action_type = ''REGISTER''\n    AND event_type = ''birth''\n    AND (created_at::date - (declaration->>''child_dob'')::date) < 365\n)\nSELECT * from population_sum;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}'),
