INSERT INTO "PUBLIC"."QUERY" VALUES
(X'f878a7400b1f77d0f1fcd16ff3308634a6334396d77c9eee52ed56036a98effa', 1, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH top_level_locations AS (\n  SELECT name\n  FROM analytics.locations\n  WHERE parent_id IS NULL\n),\npopulation_sum AS (\n  SELECT \n    SUM(total_population) AS total_population\n  FROM \n    analytics.location_statistics s\n  JOIN \n    top_level_locations l ON s.name = l.name\n  WHERE \n    s.year = [[year]]\n),\nbirth_rate AS (\n  SELECT \n    AVG(crude_birth_rate) AS country_birth_rate\n  FROM \n    analytics.location_statistics\n  WHERE \n    year = [[year]]\n),\nregistered_births AS (\n  SELECT \n    COUNT(*) AS registered_count\n  FROM \n    analytics.event_actions\n  WHERE \n    action_type = ''REGISTER''\n    AND event_type = ''birth''\n    AND (created_at::date - (declaration->>''child_dob'')::date) < 365\n)\nSELECT \n  r.registered_count / (p.total_population / 1000 * b.country_birth_rate) * 100 AS registered_birth_percentage\nFROM \n  registered_births r,\n  birth_rate b,\n  population_sum p;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}'),
(X'9f2e3606397e15be21a417393ad1ea982d1f07cc42d4fc04340611423b6cf55a', 20, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"type":"native","middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"process-viz-settings?":false,"userland-query?":true},"cache-strategy":null,"native":{"template-tags":{"year":{"type":"text","name":"year","id":"be1ae479-6da3-4c17-b7fe-e412a701c0b7","display-name":"Year"}},"query":"WITH top_level_locations AS (\n  SELECT name\n  FROM analytics.locations\n  WHERE parent_id IS NULL\n),\npopulation_sum AS (\n  SELECT \n    SUM(total_population) AS total_population\n  FROM \n    analytics.location_statistics s\n  JOIN \n    top_level_locations l ON s.name = l.name\n  WHERE \n    s.year = [[{{year}}]]\n),\nbirth_rate AS (\n  SELECT \n    AVG(crude_birth_rate) AS country_birth_rate\n  FROM \n    analytics.location_statistics\n  WHERE \n    year = [[{{year}}]]\n),\nregistered_births AS (\n  SELECT \n    COUNT(*) AS registered_count\n  FROM \n    analytics.event_actions\n  WHERE \n    action_type = ''REGISTER''\n    AND event_type = ''birth''\n    AND (created_at::date - (declaration->>''child_dob'')::date) < 365\n)\nSELECT \n  r.registered_count / (p.total_population / 1000 * b.country_birth_rate) * 100 AS registered_birth_percentage\nFROM \n  registered_births r,\n  birth_rate b,\n  population_sum p;"},"viz-settings":{"gauge.segments":[{"min":0,"max":25,"color":"hsla(358, 71%, 62%, 1)","label":""},{"min":25,"max":75,"color":"#F9CF48","label":""},{"min":75,"max":100,"color":"#84BB4C","label":""}],"column_settings":{"[\"name\",\"registered_birth_percentage\"]":{"suffix":"%"}}},"database":2,"parameters":[{"id":"be1ae479-6da3-4c17-b7fe-e412a701c0b7","type":"string/=","target":["variable",["template-tag","year"]],"value":null}]}'),
(X'11f0cd321269ec51c5f6591614403c757b162cb6068fee99d6034f7c8bd3a0d1', 30, '{"database":2,"type":"native","native":{"template-tags":{"year":{"id":"be1ae479-6da3-4c17-b7fe-e412a701c0b7","type":"number","name":"year","display-name":"Year"}},"query":"WITH top_level_locations AS (\n  SELECT name\n  FROM analytics.locations\n  WHERE parent_id IS NULL\n),\npopulation_sum AS (\n  SELECT \n    SUM(total_population) AS total_population\n  FROM \n    analytics.location_statistics s\n  JOIN \n    top_level_locations l ON s.name = l.name\n  WHERE \n    s.year = [[{{year}}]]\n),\nbirth_rate AS (\n  SELECT \n    AVG(crude_birth_rate) AS country_birth_rate\n  FROM \n    analytics.location_statistics\n  WHERE \n    year = [[{{year}}]]\n),\nregistered_births AS (\n  SELECT \n    COUNT(*) AS registered_count\n  FROM \n    analytics.event_actions\n  WHERE \n    action_type = ''REGISTER''\n    AND event_type = ''birth''\n    AND (created_at::date - (declaration->>''child_dob'')::date) < 365\n)\nSELECT \n  r.registered_count / (p.total_population / 1000 * b.country_birth_rate) * 100 AS registered_birth_percentage\nFROM \n  registered_births r,\n  birth_rate b,\n  population_sum p;"},"parameters":[{"id":"be1ae479-6da3-4c17-b7fe-e412a701c0b7","type":"number/=","value":null,"target":["variable",["template-tag","year"]]}],"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');  
