INSERT INTO "PUBLIC"."QUERY" VALUES
(X'358829a556b53cdc0f3afb3fe372185cbf711ba9bf2ef08850c452d174c5f806', 355, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE administrative_area_path AS (\n    -- roots\n    SELECT\n        aa.id,\n        aa.parent_id,\n        aa.name,\n        aa.name::text AS path,\n        1 AS level\n    FROM app.administrative_areas aa\n    WHERE aa.parent_id IS NULL\n\n    UNION ALL\n\n    -- descendants\n    SELECT\n        aa.id,\n        aa.parent_id,\n        aa.name,\n        aap.path || '','' || aa.name AS path,\n        aap.level + 1\n    FROM app.administrative_areas aa\n    JOIN administrative_area_path aap\n        ON aa.parent_id = aap.id\n),\n\npivot AS (\n    SELECT\n        id,\n\n        split_part(path, '','', 1)  AS level_1_name,\n        split_part(path, '','', 2)  AS level_2_name,\n        split_part(path, '','', 3)  AS level_3_name,\n        split_part(path, '','', 4)  AS level_4_name,\n        split_part(path, '','', 5)  AS level_5_name,\n        split_part(path, '','', 6)  AS level_6_name,\n        split_part(path, '','', 7)  AS level_7_name,\n        split_part(path, '','', 8)  AS level_8_name,\n        split_part(path, '','', 9)  AS level_9_name,\n        split_part(path, '','', 10) AS level_10_name\n\n    FROM administrative_area_path\n)\n\nSELECT\n    l.*,\n\n    aa.name AS administrative_area_name,\n\n    aap.path AS administrative_area_path,\n    aap.level AS administrative_area_level,\n\n    p.level_1_name,\n    p.level_2_name,\n    p.level_3_name,\n    p.level_4_name,\n    p.level_5_name,\n    p.level_6_name,\n    p.level_7_name,\n    p.level_8_name,\n    p.level_9_name,\n    p.level_10_name\n\nFROM app.locations l\n\nLEFT JOIN app.administrative_areas aa\n    ON aa.id = l.administrative_area_id\n\nLEFT JOIN administrative_area_path aap\n    ON aap.id = aa.id\n\nLEFT JOIN pivot p\n    ON p.id = aa.id;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}'),
