INSERT INTO "PUBLIC"."QUERY" VALUES
(X'4869e83d2aa7d483d5715812c84e1c4c499654e5b760cf9ae8c9d2b18cae0c48', 20, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE\n  administrative_area_path AS (\n    -- roots\n    SELECT\n      aa.id,\n      aa.parent_id,\n      aa.name,\n      aa.name::TEXT AS administrative_area_path,\n      1 AS LEVEL\n    FROM\n      analytics.administrative_areas aa\n    WHERE\n      aa.parent_id IS NULL\n    UNION ALL\n    -- descendants\n    SELECT\n      aa.id,\n      aa.parent_id,\n      aa.name,\n      aap.administrative_area_path || '','' || aa.name,\n      aap.level + 1\n    FROM\n      analytics.administrative_areas aa\n      JOIN administrative_area_path aap ON aa.parent_id = aap.id\n  )\nSELECT\n  *\nFROM\n  administrative_area_path"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}'),
(X'94e35da3a1993b783f567a4b6ef47a9f3d117bfaee35b0d6acd8b3ff802a5c8a', 1197, SYSTEM_COMBINE_CLOB(225)),
