(X'c6cb18140918d7014303e66b5926c0fc33039b8b48e49448b1c94ff49facea92', 116, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE\n  levels AS (\n    -- root = 1, children increment\n    SELECT\n      id,\n      parent_id,\n      1 AS LEVEL\n    FROM\n      analytics.administrative_areas\n    WHERE\n      parent_id IS NULL\n    UNION ALL\n    SELECT\n      l.id,\n      l.parent_id,\n      lv.level + 1\n    FROM\n      analytics.administrative_areas l\n      JOIN levels lv ON l.parent_id = lv.id\n  ),\n  -- ancestor/descendant closure: every node is ancestor of itself and all its descendants\n  closure AS (\n    SELECT\n      id AS ancestor_id,\n      id AS descendant_id\n    FROM\n      analytics.administrative_areas\n    UNION ALL\n    SELECT\n      c.ancestor_id,\n      l.id AS descendant_id\n    FROM\n      closure c\n      JOIN analytics.administrative_areas l ON l.parent_id = c.descendant_id\n  ),\n  -- counts at leaf/origin locations by year\n  counts AS (\n    SELECT\n      loc.administrative_area_id AS location_id,\n      EXTRACT(\n        YEAR\n        FROM\n          ea.created_at\n      )::int AS YEAR,\n      COUNT(*) AS cnt\n    FROM\n      analytics.event_actions ea\n      JOIN analytics.locations loc ON loc.id = ea.created_at_location\n    WHERE\n      ea.action_type = ''REGISTER''\n      AND ea.event_type = ''birth''\n      AND ea.created_at IS NOT NULL\n      AND ea.created_at_location IS NOT NULL\n      AND (ea.declaration ->> ''child_dob'')::date > ea.created_at::date - INTERVAL ''365 days''\n    GROUP BY\n      loc.administrative_area_id,\n      YEAR\n  ),\n  -- roll up descendant counts to each ancestor (this is the named query)\n  birth_registrations_per_location AS (\n    SELECT\n      c.ancestor_id AS location_id,\n      cnt.year,\n      SUM(cnt.cnt) AS register_count\n    FROM\n      closure c\n      JOIN counts cnt ON cnt.location_id = c.descendant_id\n    GROUP BY\n      c.ancestor_id,\n      cnt.year\n  )\nSELECT\n  l.id,\n  l.name,\n  s.year,\n  s.crude_birth_rate,\n  s.total_population,\n  (s.total_population / 1000 * s.crude_birth_rate) AS estimated_births,\n  COALESCE(br.register_count, 0) AS register_count,\n  COALESCE(\n    register_count / NULLIF(\n      (s.total_population / 1000 * s.crude_birth_rate),\n      0\n    ) * 100,\n    0\n  ) AS completeness_rate,\n  lv.level,\n  ll.name AS level_name\nFROM\n  analytics.administrative_areas l\n  JOIN analytics.location_statistics s ON s.name = l.name\n  LEFT JOIN birth_registrations_per_location br ON br.location_id = l.id\n  AND br.year = s.year\n  LEFT JOIN levels lv ON lv.id = l.id\n  LEFT JOIN analytics.location_levels ll ON ll.level = lv.level\nORDER BY\n  s.year DESC,\n  register_count DESC;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');         
INSERT INTO "PUBLIC"."QUERY" VALUES
(X'13eb978ed61829b95861ea5241ab46bbff4b30d4c1b57ef6c7fe276beccf7d03', 72, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"type":"native","middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"process-viz-settings?":false,"userland-query?":true},"cache-strategy":null,"native":{"template-tags":{},"query":"WITH RECURSIVE\n  levels AS (\n    -- root = 1, children increment\n    SELECT\n      id,\n      parent_id,\n      1 AS LEVEL\n    FROM\n      analytics.administrative_areas\n    WHERE\n      parent_id IS NULL\n    UNION ALL\n    SELECT\n      l.id,\n      l.parent_id,\n      lv.level + 1\n    FROM\n      analytics.administrative_areas l\n      JOIN levels lv ON l.parent_id = lv.id\n  ),\n  -- ancestor/descendant closure: every node is ancestor of itself and all its descendants\n  closure AS (\n    SELECT\n      id AS ancestor_id,\n      id AS descendant_id\n    FROM\n      analytics.administrative_areas\n    UNION ALL\n    SELECT\n      c.ancestor_id,\n      l.id AS descendant_id\n    FROM\n      closure c\n      JOIN analytics.administrative_areas l ON l.parent_id = c.descendant_id\n  ),\n  -- counts at leaf/origin locations by year\n  counts AS (\n    SELECT\n      loc.administrative_area_id AS location_id,\n      EXTRACT(\n        YEAR\n        FROM\n          ea.created_at\n      )::int AS YEAR,\n      COUNT(*) AS cnt\n    FROM\n      analytics.event_actions ea\n      JOIN analytics.locations loc ON loc.id = ea.created_at_location\n    WHERE\n      ea.action_type = ''REGISTER''\n      AND ea.event_type = ''birth''\n      AND ea.created_at IS NOT NULL\n      AND ea.created_at_location IS NOT NULL\n      AND (ea.declaration ->> ''child_dob'')::date > ea.created_at::date - INTERVAL ''365 days''\n    GROUP BY\n      loc.administrative_area_id,\n      YEAR\n  ),\n  -- roll up descendant counts to each ancestor (this is the named query)\n  birth_registrations_per_location AS (\n    SELECT\n      c.ancestor_id AS location_id,\n      cnt.year,\n      SUM(cnt.cnt) AS register_count\n    FROM\n      closure c\n      JOIN counts cnt ON cnt.location_id = c.descendant_id\n    GROUP BY\n      c.ancestor_id,\n      cnt.year\n  )\nSELECT\n  l.id,\n  l.name,\n  s.year,\n  s.crude_birth_rate,\n  s.total_population,\n  (s.total_population / 1000 * s.crude_birth_rate) AS estimated_births,\n  COALESCE(br.register_count, 0) AS register_count,\n  COALESCE(\n    register_count / NULLIF(\n      (s.total_population / 1000 * s.crude_birth_rate),\n      0\n    ) * 100,\n    0\n  ) AS completeness_rate,\n  lv.level,\n  ll.name AS level_name\nFROM\n  analytics.administrative_areas l\n  JOIN analytics.location_statistics s ON s.name = l.name\n  LEFT JOIN birth_registrations_per_location br ON br.location_id = l.id\n  AND br.year = s.year\n  LEFT JOIN levels lv ON lv.id = l.id\n  LEFT JOIN analytics.location_levels ll ON ll.level = lv.level\nORDER BY\n  s.year DESC,\n  register_count DESC;"},"viz-settings":{"graph.x_axis.scale":"ordinal","graph.dimensions":["name"],"table.pivot_column":"crude_birth_rate","table.cell_column":"year","graph.metrics":[]},"database":2}'),
(X'e12029cdf0fcd93f97aa451aafe3bf998f70cefc5d7e6a97dbcc5f74c6c10f0e', 35, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"type":"native","middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"native":{"template-tags":{"year":{"id":"be1ae479-6da3-4c17-b7fe-e412a701c0b7","type":"number","name":"year","display-name":"Year","default":"2026"}},"query":"WITH\n  top_level_locations AS (\n    SELECT\n      name\n    FROM\n      analytics.administrative_areas\n    WHERE\n      parent_id IS NULL\n  ),\n  population_sum AS (\n    SELECT\n      SUM(total_population) AS total_population\n    FROM\n      analytics.location_statistics s\n      JOIN top_level_locations l ON s.name = l.name [[WHERE\n      s.year ={{year}}]]\n  ),\n  birth_rate AS (\n    SELECT\n      AVG(crude_birth_rate) AS country_birth_rate\n    FROM\n      analytics.location_statistics [[    WHERE\n      YEAR ={{year}}]]\n  ),\n  registered_births AS (\n    SELECT\n      COUNT(*) AS registered_count\n    FROM\n      analytics.event_actions\n    WHERE\n      action_type = ''REGISTER''\n      AND event_type = ''birth''\n      AND (\n        created_at::date - (declaration ->> ''child_dob'')::date\n      ) < 365 [[AND EXTRACT(\n    YEAR FROM created_at::date\n) = {{year}}]]\n  )\nSELECT\n  r.registered_count / (p.total_population / 1000 * b.country_birth_rate) * 100 AS registered_birth_percentage\nFROM\n  registered_births r,\n  birth_rate b,\n  population_sum p;"},"viz-settings":{"gauge.segments":[{"min":0,"max":25,"color":"hsla(358, 71%, 62%, 1)","label":""},{"min":25,"max":75,"color":"#F9CF48","label":""},{"min":75,"max":100,"color":"#84BB4C","label":""}],"column_settings":{"[\"name\",\"registered_birth_percentage\"]":{"suffix":"%"}}},"database":2,"parameters":[{"type":"number/=","value":["2023"],"id":"3e9b2029","target":["variable",["template-tag","year"]]}]}');     
