(X'bfc04c58aa9d6c2b146fa85291174ab69b605d051db0d74644c143c2913aa0c4', 42, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"type":"native","middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"native":{"template-tags":{"year":{"id":"be1ae479-6da3-4c17-b7fe-e412a701c0b7","type":"number","name":"year","display-name":"Year","default":"2026"}},"query":"WITH\n  top_level_locations AS (\n    SELECT\n      name\n    FROM\n      analytics.administrative_areas\n    WHERE\n      parent_id IS NULL\n  ),\n  population_sum AS (\n    SELECT\n      SUM(total_population) AS total_population\n    FROM\n      analytics.location_statistics s\n      JOIN top_level_locations l ON s.name = l.name [[WHERE\n      s.year ={{year}}]]\n  ),\n  birth_rate AS (\n    SELECT\n      AVG(crude_birth_rate) AS country_birth_rate\n    FROM\n      analytics.location_statistics [[    WHERE\n      YEAR ={{year}}]]\n  ),\n  registered_births AS (\n    SELECT\n      COUNT(*) AS registered_count\n    FROM\n      analytics.event_actions\n    WHERE\n      action_type = ''REGISTER''\n      AND event_type = ''birth''\n      AND (\n        created_at::date - (declaration ->> ''child_dob'')::date\n      ) < 365 [[AND EXTRACT(\n    YEAR FROM created_at::date\n) = {{year}}]]\n  )\nSELECT\n  r.registered_count / (p.total_population / 1000 * b.country_birth_rate) * 100 AS registered_birth_percentage\nFROM\n  registered_births r,\n  birth_rate b,\n  population_sum p;"},"viz-settings":{"gauge.segments":[{"min":0,"max":25,"color":"hsla(358, 71%, 62%, 1)","label":""},{"min":25,"max":75,"color":"#F9CF48","label":""},{"min":75,"max":100,"color":"#84BB4C","label":""}],"column_settings":{"[\"name\",\"registered_birth_percentage\"]":{"suffix":"%"}}},"database":2,"parameters":[{"type":"number/=","value":null,"id":"3e9b2029","target":["variable",["template-tag","year"]]}]}'),
