(X'bf8f8ffc54ddf86d6c469f7317786a98bcdfe6161228f3361cd969ab74fa6f60', 28, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE\n  administrative_area_path AS (\n    -- roots\n    SELECT\n      aa.id,\n      aa.parent_id,\n      aa.name,\n      aa.name::TEXT AS administrative_area_path,\n      1 AS LEVEL\n    FROM\n      analytics.administrative_areas aa\n    WHERE\n      aa.parent_id IS NULL\n    UNION ALL\n    -- descendants\n    SELECT\n      aa.id,\n      aa.parent_id,\n      aa.name,\n      aap.administrative_area_path || '','' || aa.name,\n      aap.level + 1\n    FROM\n      analytics.administrative_areas aa\n      JOIN administrative_area_path aap ON aa.parent_id = aap.id\n  ),\n  pivot AS (\n    SELECT\n      id,\n      split_part(administrative_area_path, '','', 1) AS level_1_name,\n      split_part(administrative_area_path, '','', 2) AS level_2_name,\n      split_part(administrative_area_path, '','', 3) AS level_3_name,\n      split_part(administrative_area_path, '','', 4) AS level_4_name,\n      split_part(administrative_area_path, '','', 5) AS level_5_name,\n      split_part(administrative_area_path, '','', 6) AS level_6_name,\n      split_part(administrative_area_path, '','', 7) AS level_7_name,\n      split_part(administrative_area_path, '','', 8) AS level_8_name,\n      split_part(administrative_area_path, '','', 9) AS level_9_name,\n      split_part(administrative_area_path, '','', 10) AS level_10_name\n    FROM\n      administrative_area_path\n  )\nSELECT\n  l.id::TEXT AS id,\n  l.name,\n  l.location_type,\n  l.administrative_area_id,\n  aa.name AS administrative_area_name,\n  aap.administrative_area_path,\n  aap.level AS administrative_area_level,\n  -- include location itself in the final full path\n  CASE\n    WHEN aap.administrative_area_path IS NOT NULL THEN aap.administrative_area_path || '','' || l.name\n    ELSE l.name\n  END AS full_path,\n  p.level_1_name,\n  p.level_2_name,\n  p.level_3_name,\n  p.level_4_name,\n  p.level_5_name,\n  p.level_6_name,\n  p.level_7_name,\n  p.level_8_name,\n  p.level_9_name,\n  p.level_10_name\nFROM\n  analytics.locations l\n  LEFT JOIN analytics.administrative_areas aa ON aa.id = l.administrative_area_id\n  LEFT JOIN administrative_area_path aap ON aap.id = aa.id\n  LEFT JOIN pivot p ON p.id = aa.id;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}'),
(X'0c8562a39e7ec3948baf29f825a3fddb8cef096c190ae642baec0ad3bcc5954d', 58, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"type":"native","middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"process-viz-settings?":false,"userland-query?":true},"cache-strategy":null,"native":{"template-tags":{},"query":"WITH RECURSIVE\n  administrative_area_path AS (\n    -- roots\n    SELECT\n      aa.id,\n      aa.parent_id,\n      aa.name,\n      aa.name::TEXT AS administrative_area_path,\n      1 AS LEVEL\n    FROM\n      analytics.administrative_areas aa\n    WHERE\n      aa.parent_id IS NULL\n    UNION ALL\n    -- descendants\n    SELECT\n      aa.id,\n      aa.parent_id,\n      aa.name,\n      aap.administrative_area_path || '','' || aa.name,\n      aap.level + 1\n    FROM\n      analytics.administrative_areas aa\n      JOIN administrative_area_path aap ON aa.parent_id = aap.id\n  ),\n  pivot AS (\n    SELECT\n      id,\n      split_part(administrative_area_path, '','', 1) AS level_1_name,\n      split_part(administrative_area_path, '','', 2) AS level_2_name,\n      split_part(administrative_area_path, '','', 3) AS level_3_name,\n      split_part(administrative_area_path, '','', 4) AS level_4_name,\n      split_part(administrative_area_path, '','', 5) AS level_5_name,\n      split_part(administrative_area_path, '','', 6) AS level_6_name,\n      split_part(administrative_area_path, '','', 7) AS level_7_name,\n      split_part(administrative_area_path, '','', 8) AS level_8_name,\n      split_part(administrative_area_path, '','', 9) AS level_9_name,\n      split_part(administrative_area_path, '','', 10) AS level_10_name\n    FROM\n      administrative_area_path\n  )\nSELECT\n  l.id::TEXT AS id,\n  l.name,\n  l.location_type,\n  l.administrative_area_id,\n  aa.name AS administrative_area_name,\n  aap.administrative_area_path,\n  aap.level AS administrative_area_level,\n  -- include location itself in the final full path\n  CASE\n    WHEN aap.administrative_area_path IS NOT NULL THEN aap.administrative_area_path || '','' || l.name\n    ELSE l.name\n  END AS full_path,\n  p.level_1_name,\n  p.level_2_name,\n  p.level_3_name,\n  p.level_4_name,\n  p.level_5_name,\n  p.level_6_name,\n  p.level_7_name,\n  p.level_8_name,\n  p.level_9_name,\n  p.level_10_name\nFROM\n  analytics.locations l\n  LEFT JOIN analytics.administrative_areas aa ON aa.id = l.administrative_area_id\n  LEFT JOIN administrative_area_path aap ON aap.id = aa.id\n  LEFT JOIN pivot p ON p.id = aa.id;"},"viz-settings":{"table.pivot_column":"created_at","table.cell_column":"valid_until"},"database":2}');       
