INSERT INTO "PUBLIC"."REPORT_CARD" VALUES
(52, TIMESTAMP WITH TIME ZONE '2025-08-19 09:28:13.711286+03', TIMESTAMP WITH TIME ZONE '2025-09-04 13:28:10.220119+03', 'Locations', NULL, 'table', '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE r AS (\n  SELECT\n    l.id         AS location_id,\n    l.name,\n    l.parent_id,\n    0 AS level\n  FROM analytics.locations l\n\n  UNION ALL\n\n  SELECT\n    r.location_id,\n    p.name,\n    p.parent_id,\n    r.level + 1\n  FROM r\n  JOIN analytics.locations p ON r.parent_id = p.id\n)\nSELECT\n  location_id,\n  MAX(CASE WHEN level = 0 THEN name END) AS level_0,\n  MAX(CASE WHEN level = 1 THEN name END) AS level_1,\n  MAX(CASE WHEN level = 2 THEN name END) AS level_2,\n  MAX(CASE WHEN level = 3 THEN name END) AS level_3\nFROM r\nGROUP BY location_id;"}}', '{"table.pivot_column":"level_3","table.cell_column":"level_2"}', 1, 2, NULL, 'native', TRUE, 5, NULL, NULL, FALSE, NULL, NULL, '[{"database_type":"uuid","semantic_type":null,"lib/deduplicated-name":"location_id","lib/original-name":"location_id","name":"location_id","lib/source":"source/native","source":"native","field_ref":["field","location_id",{"base-type":"type/UUID"}],"effective_type":"type/UUID","display_name":"location_id","fingerprint":{"global":{"distinct-count":337,"nil%":0.0},"type":{"type/Text":{"percent-json":0.0,"percent-url":0.0,"percent-email":0.0,"percent-state":0.0,"average-length":36.0}}},"base_type":"type/UUID"},{"database_type":"text","semantic_type":null,"lib/deduplicated-name":"level_0","lib/original-name":"level_0","name":"level_0","lib/source":"source/native","source":"native","field_ref":["field","level_0",{"base-type":"type/Text"}],"effective_type":"type/Text","display_name":"level_0","fingerprint":{"global":{"distinct-count":335,"nil%":0.0},"type":{"type/Text":{"percent-json":0.0,"percent-url":0.0,"percent-email":0.0,"percent-state":0.0,"average-length":23.827893175074184}}},"base_type":"type/Text"},{"database_type":"text","semantic_type":null,"lib/deduplic