INSERT INTO "PUBLIC"."REPORT_CARD" VALUES
(124, TIMESTAMP WITH TIME ZONE '2025-09-12 10:07:18.436943+03', TIMESTAMP WITH TIME ZONE '2026-07-06 14:27:39.684624+06', 'Births completeness rates', 'Completeness rates per location per year, based on country provided population and crude birth rate statistics', 'table', '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE\n  levels AS (\n    -- root = 1, children increment\n    SELECT\n      id,\n      parent_id,\n      1 AS LEVEL\n    FROM\n      analytics.administrative_areas\n    WHERE\n      parent_id IS NULL\n    UNION ALL\n    SELECT\n      l.id,\n      l.parent_id,\n      lv.level + 1\n    FROM\n      analytics.administrative_areas l\n      JOIN levels lv ON l.parent_id = lv.id\n  ),\n  -- ancestor/descendant closure: every node is ancestor of itself and all its descendants\n  closure AS (\n    SELECT\n      id AS ancestor_id,\n      id AS descendant_id\n    FROM\n      analytics.administrative_areas\n    UNION ALL\n    SELECT\n      c.ancestor_id,\n      l.id AS descendant_id\n    FROM\n      closure c\n      JOIN analytics.administrative_areas l ON l.parent_id = c.descendant_id\n  ),\n  -- counts at leaf/origin locations by year\n  counts AS (\n    SELECT\n      loc.administrative_area_id AS location_id,\n      EXTRACT(\n        YEAR\n        FROM\n          ea.created_at\n      )::int AS YEAR,\n      COUNT(*) AS cnt\n    FROM\n      analytics.event_actions ea\n      JOIN analytics.locations loc ON loc.id = ea.created_at_location\n    WHERE\n      ea.action_type = ''REGISTER''\n      AND ea.event_type = ''birth''\n      AND ea.created_at IS NOT NULL\n      AND ea.created_at_location IS NOT NULL\n      AND (ea.declaration ->> ''child_dob'')::date > ea.created_at::date - INTERVAL ''365 days''\n    GROUP BY\n      loc.administrative_area_id,\n      YEAR\n  ),\n  -- roll up descendant counts to each ancestor (this is the named query)\n  birth_registrations_per_location AS (\n    SELECT\n      c.ancestor_id AS location_id,\n      cnt.year,\n      SUM(cnt.cnt) AS register_count\n    FROM\n      closure c\n      JOIN counts cnt ON cnt.location_id = c.descendant_id\n    GROUP BY\n      c.ancestor_id,\n      cnt.year\n  )\nSELECT\n  l.id,\n  l.name,\n  s.year,\n  s.crude_birth_rate,\n  s.total_population,\n  (s.total_population / 1000 * s.crude_birth_rate) AS estimated_births,\n  COALESCE(br.register_count, 0) AS register_count,\n  COALESCE(\n    register_count / NULLIF(\n      (s.total_population / 1000 * s.crude_birth_rate),\n      0\n    ) * 100,\n    0\n  ) AS completeness_rate,\n  lv.level,\n  ll.name AS level_name\nFROM\n  analytics.administrative_areas l\n  JOIN analytics.location_statistics s ON s.name = l.name\n  LEFT JOIN birth_registrations_per_location br ON br.location_id = l.id\n  AND br.year = s.year\n  LEFT JOIN levels lv ON lv.id = l.id\n  LEFT JOIN analytics.location_levels ll ON ll.level = lv.level\nORDER BY\n  s.year DESC,\n  register_count DESC;"}}', '{"graph.x_axis.scale":"ordinal","graph.dimensions":["name"],"graph.metrics":[],"table.pivot_column":"crude_birth_rate","table.cell_column":"year"}', 1, 2, NULL, 'native', FALSE, 9, NULL, NULL, FALSE, NULL, NULL, SYSTEM_COMBINE_CLOB(254), 1, 'dTJlMmm0y9G98CTByr9-S', '[]', '[]', TRUE, 'v0.56.4 (aeaacd0)', 'model', NULL, TIMESTAMP WITH TIME ZONE '2026-07-06 14:27:39.680436+06', TIMESTAMP WITH TIME ZONE '2026-07-06 14:28:27.786788+06', 95, FALSE, NULL, NULL, NULL, 22),
(125, TIMESTAMP WITH TIME ZONE '2025-09-12 10:47:16.128521+03', TIMESTAMP WITH TIME ZONE '2025-09-12 11:03:33.835271+03', 'Births completeness rates by state', 'Completeness rates per location per year, based on country provided population and crude birth rate statistics', 'bar', '{"database":2,"type":"query","query":{"joins":[{"fields":"all","strategy":"left-join","alias":"Admin Locations - name","condition":["=",["field","name",{"base-type":"type/Text"}],["field",276,{"base-type":"type/Text","join-alias":"Admin Locations - name"}]],"source-table":"card__92"}],"source-table":"card__124","filter":["=",["field","level",{"base-type":"type/Integer","join-alias":"Admin Locations - name"}],1]}}', '{"graph.y_axis.title_text":"Completness Rates","graph.show_values":false,"graph.x_axis.labels_enabled":false,"graph.y_axis.labels_enabled":true,"graph.y_axis.scale":"linear","graph.metrics":["completeness_rate"],"graph.y_axis.auto_range":false,"graph.x_axis.scale":"ordinal","graph.dimensions":["name"]}', 1, 2, NULL, 'query', FALSE, 9, NULL, NULL, FALSE, NULL, NULL, SYSTEM_COMBINE_CLOB(255), NULL, 'SlnPXcddawaoWsDK7_MIV', '[]', '[]', TRUE, 'v0.56.4 (aeaacd0)', 'question', NULL, TIMESTAMP WITH TIME ZONE '2025-09-12 11:03:33.833253+03', TIMESTAMP WITH TIME ZONE '2025-09-12 11:20:16.820095+03', 27, FALSE, NULL, 124, NULL, 22);            
