(158, TIMESTAMP WITH TIME ZONE '2026-07-06 13:36:25.247734+06', TIMESTAMP WITH TIME ZONE '2026-07-06 13:36:25.247734+06', 'Administrative Areas', NULL, 'table', '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE\n  administrative_area_path AS (\n    -- roots\n    SELECT\n      aa.id,\n      aa.parent_id,\n      aa.name,\n      aa.name::TEXT AS administrative_area_path,\n      1 AS LEVEL\n    FROM\n      analytics.administrative_areas aa\n    WHERE\n      aa.parent_id IS NULL\n    UNION ALL\n    -- descendants\n    SELECT\n      aa.id,\n      aa.parent_id,\n      aa.name,\n      aap.administrative_area_path || '','' || aa.name,\n      aap.level + 1\n    FROM\n      analytics.administrative_areas aa\n      JOIN administrative_area_path aap ON aa.parent_id = aap.id\n  )\nSELECT\n  *\nFROM\n  administrative_area_path"}}', '{"table.pivot_column":"level","table.cell_column":"administrative_area_path"}', 1, 2, NULL, 'native', FALSE, NULL, NULL, NULL, FALSE, NULL, NULL, '[{"database_type":"text","semantic_type":"type/PK","lib/deduplicated-name":"id","lib/original-name":"id","name":"id","lib/source":"source/native","source":"native","field_ref":["field","id",{"base-type":"type/Text"}],"effective_type":"type/Text","display_name":"id","fingerprint":null,"base_type":"type/Text"},{"database_type":"text","semantic_type":null,"lib/deduplicated-name":"parent_id","lib/original-name":"parent_id","name":"parent_id","lib/source":"source/native","source":"native","field_ref":["field","parent_id",{"base-type":"type/Text"}],"effective_type":"type/Text","display_name":"parent_id","fingerprint":{"global":{"distinct-count":21,"nil%":0.04761904761904762},"type":{"type/Text":{"percent-json":0,"percent-url":0,"percent-email":0,"percent-state":0,"average-length":34.285714285714285}}},"base_type":"type/Text"},{"database_type":"text","semantic_type":"type/Name","lib/deduplicated-name":"name","lib/original-name":"name","name":"name","lib/source":"source/native","sou