(29, 'Locations', 'Locations {"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE r AS (\n  SELECT\n    l.id         AS location_id,\n    l.name,\n    l.parent_id,\n    0 AS level\n  FROM analytics.locations l\n\n  UNION ALL\n\n  SELECT\n    r.location_id,\n    p.name,\n    p.parent_id,\n    r.level + 1\n  FROM r\n  JOIN analytics.locations p ON r.parent_id = p.id\n)\nSELECT\n  location_id,\n  MAX(CASE WHEN level = 0 THEN name END) AS level_0,\n  MAX(CASE WHEN level = 1 THEN name END) AS level_1,\n  MAX(CASE WHEN level = 2 THEN name END) AS level_2,\n  MAX(CASE WHEN level = 3 THEN name END) AS level_3\nFROM r\nGROUP BY location_id;"}}', 'dataset', '{"name":"Locations","description":null,"collection_name":"OpenCRVS Core Dashboards"}', '{"description":null,"archived":true,"display_type":"table","collection_position":9,"database_id":2,"collection_id":5,"official_collection":null,"name":"Locations","collection_name":"OpenCRVS Core Dashboards","collection_authority_level":null,"creator_id":1,"updated_at":"2025-09-04T13:28:10.220119+03:00","moderated_status":null,"dataset_query":"{\"database\":2,\"type\":\"native\",\"native\":{\"template-tags\":{},\"query\":\"WITH RECURSIVE r AS (\\n  SELECT\\n    l.id         AS location_id,\\n    l.name,\\n    l.parent_id,\\n    0 AS level\\n  FROM analytics.locations l\\n\\n  UNION ALL\\n\\n  SELECT\\n    r.location_id,\\n    p.name,\\n    p.parent_id,\\n    r.level + 1\\n  FROM r\\n  JOIN analytics.locations p ON r.parent_id = p.id\\n)\\nSELECT\\n  location_id,\\n  MAX(CASE WHEN level = 0 THEN name END) AS level_0,\\n  MAX(CASE WHEN level = 1 THEN name END) AS level_1,\\n  MAX(CASE WHEN level = 2 THEN name END) AS level_2,\\n  MAX(CASE WHEN level = 3 THEN name END) AS level_3\\nFROM r\\nGROUP BY location_id;\"}}","last_editor_id":1,"collection_location":"/","id":52,"last_edited_at":"2025-09-04T10:47:59.446038+03:00","dashboardcard_count":1,"collection_type":null,"display":"table","archived_directly":false,"verified":null,"dashboard_id":null,"created_at":"2025-08-19T09:28:13.711286+03:00","model":"dataset"}', TIMESTAMP WITH TIME ZONE '2026-07-06 14:03:34.547273+06', TIMESTAMP WITH TIME ZONE '2026-07-06 14:03:34.547273+06', TRUE, TIMESTAMP WITH TIME ZONE '2025-09-04 13:28:10.220119+03', TRUE, 5, NULL, 'Locations', FALSE, TIMESTAMP WITH TIME ZONE '2025-09-04 10:47:59.446038+03', 1, '[]', NULL, 1, '52', 'table', TIMESTAMP WITH TIME ZONE '2025-09-04 12:33:12.351558+03', 2, 1, 16, TIMESTAMP WITH TIME ZONE '2025-08-19 09:28:13.711286+03', NULL);            
