(41, 'Printed + Registered Distinct printed and registered records', 'Printed + Registered Distinct printed and registered records {"database":2,"type":"native","native":{"template-tags":{},"query":"WITH printed AS (\n  SELECT *\n  FROM analytics.event_actions\n  WHERE action_type = ''PRINT_CERTIFICATE''\n),\nregistered AS (\n  SELECT *\n  FROM analytics.event_actions\n  WHERE action_type = ''REGISTER''\n)\n-- all printed, plus registered that are not printed\nSELECT p.*\nFROM printed p\nUNION ALL\nSELECT r.*\nFROM registered r\nLEFT JOIN printed p USING (event_id)\nWHERE p.event_id IS NULL;"}}', 'dataset', '{"name":"Printed + Registered","description":"Distinct printed and registered records","collection_name":"Models"}', '{"description":"Distinct printed and registered records","archived":false,"display_type":"table","collection_position":null,"database_id":2,"collection_id":7,"official_collection":null,"name":"Printed + Registered","collection_name":"Models","collection_authority_level":null,"creator_id":1,"updated_at":"2025-10-10T11:08:45.675529+03:00","moderated_status":null,"dataset_query":"{\"database\":2,\"type\":\"native\",\"native\":{\"template-tags\":{},\"query\":\"WITH printed AS (\\n  SELECT *\\n  FROM analytics.event_actions\\n  WHERE action_type = ''PRINT_CERTIFICATE''\\n),\\nregistered AS (\\n  SELECT *\\n  FROM analytics.event_actions\\n  WHERE action_type = ''REGISTER''\\n)\\n-- all printed, plus registered that are not printed\\nSELECT p.*\\nFROM printed p\\nUNION ALL\\nSELECT r.*\\nFROM registered r\\nLEFT JOIN printed p USING (event_id)\\nWHERE p.event_id IS NULL;\"}}","last_editor_id":1,"collection_location":"/","id":104,"last_edited_at":"2025-10-10T11:08:45.692924+03:00","dashboardcard_count":0,"collection_type":null,"display":"table","archived_directly":false,"verified":null,"dashboard_id":null,"created_at":"2025-09-09T17:02:56.305468+03:00","model":"dataset"}', TIMESTAMP WITH TIME ZONE '2026-07-06 14:03:34.547273+06', TIMESTAMP WITH TIME ZON