(68, 'Registration by gender', 'Registration by gender', 'card', '{"name":"Registration by gender","description":null,"collection_name":"OpenCRVS Core Dashboards"}', '{"description":null,"archived":true,"display_type":"pie","collection_position":null,"database_id":2,"collection_id":5,"official_collection":null,"name":"Registration by gender","collection_name":"OpenCRVS Core Dashboards","collection_authority_level":null,"creator_id":1,"updated_at":"2025-09-04T13:28:10.220119+03:00","moderated_status":null,"dataset_query":"{\"database\":2,\"type\":\"query\",\"query\":{\"source-table\":9,\"aggregation\":[[\"cum-count\"]],\"breakout\":[[\"field\",215,{\"base-type\":\"type/Text\"}]],\"filter\":[\"=\",[\"field\",135,{\"base-type\":\"type/PostgresEnum\"}],\"REGISTER\"]}}","last_editor_id":1,"collection_location":"/","id":50,"last_edited_at":"2025-08-18T15:57:48.966984+03:00","dashboardcard_count":1,"collection_type":null,"display":"pie","archived_directly":false,"verified":null,"dashboard_id":3,"created_at":"2025-08-18T15:57:48.95962+03:00","model":"card"}', TIMESTAMP WITH TIME ZONE '2026-07-06 14:03:34.547273+06', TIMESTAMP WITH TIME ZONE '2026-07-06 14:03:34.547273+06', TRUE, TIMESTAMP WITH TIME ZONE '2025-09-04 13:28:10.220119+03', FALSE, 5, NULL, 'Registration by gender', FALSE, TIMESTAMP WITH TIME ZONE '2025-08-18 15:57:48.966984+03', 1, '[215]', 3, 1, '50', 'pie', TIMESTAMP WITH TIME ZONE '2025-09-04 12:27:09.513806+03', 2, 1, 4, TIMESTAMP WITH TIME ZONE '2025-08-18 15:57:48.95962+03', NULL),
(69, 'Registrations by State', 'Registrations by State {"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE r AS (\n  -- base: count by lowest location\n  SELECT\n    ea.created_at_location AS location_id,\n    COUNT(*)              AS count,\n    l.name,\n    l.parent_id,\n    0 AS level\n  FROM app.event_actions ea\n  JOIN app.locations l ON ea.created_at_location = l.id\n  WHERE ea.action_type = ''REGISTER''\n  GROUP BY ea.created_at_location, l.name, l.parent_id\n\n  UNION ALL\n\n  -- climb up the hierarchy\n  SELECT\n    r.location_id,\n    r.count,\n    p.name,\n    p.parent_id,\n    r.level + 1\n  FROM r\n  JOIN app.locations p ON r.parent_id = p.id\n)\n\nSELECT\n  location_id,\n  MAX(CASE WHEN level = 0 THEN name END) AS level_0,\n  MAX(CASE WHEN level = 1 THEN name END) AS level_1,\n  MAX(CASE WHEN level = 2 THEN name END) AS level_2,\n  MAX(CASE WHEN level = 3 THEN name END) AS level_3,\n  MAX(count) AS count\nFROM r\nGROUP BY location_id\nORDER BY count DESC;"}}', 'card', '{"name":"Registrations by State","description":null,"collection_name":"OpenCRVS Core Dashboards"}', '{"description":null,"archived":true,"display_type":"map","collection_position":null,"database_id":2,"collection_id":5,"official_collection":null,"name":"Registrations by State","collection_name":"OpenCRVS Core Dashboards","collection_authority_level":null,"creator_id":1,"updated_at":"2025-09-04T13:28:10.220119+03:00","moderated_status":null,"dataset_query":"{\"database\":2,\"type\":\"native\",\"native\":{\"template-tags\":{},\"query\":\"WITH RECURSIVE r AS (\\n  -- base: count by lowest location\\n  SELECT\\n    ea.created_at_location AS location_id,\\n    COUNT(*)              AS count,\\n    l.name,\\n    l.parent_id,\\n    0 AS level\\n  FROM app.event_actions ea\\n  JOIN app.locations l ON ea.created_at_location = l.id\\n  WHERE ea.action_type = ''REGISTER''\\n  GROUP BY ea.created_at_location, l.name, l.parent_id\\n\\n  UNION ALL\\n\\n  -- climb up the hierarchy\\n  SELECT\\n    r.location_id,\\n    r.count,\\n    p.name,\\n    p.parent_id,\\n    r.level + 1\\n  FROM r\\n  JOIN app.locations p ON r.parent_id = p.id\\n)\\n\\nSELECT\\n  location_id,\\n  MAX(CASE WHEN level = 0 THEN name END) AS level_0,\\n  MAX(CASE WHEN level = 1 THEN name END) AS level_1,\\n  MAX(CASE WHEN level = 2 THEN name END) AS level_2,\\n  MAX(CASE WHEN level = 3 THEN name END) AS level_3,\\n  MAX(count) AS count\\nFROM r\\nGROUP BY location_id\\nORDER BY count DESC;\"}}","last_editor_id":1,"collection_location":"/","id":51,"last_edited_at":"2025-08-20T13:44:38.388228+03:00","dashboardcard_count":1,"collection_type":null,"display":"map","archived_directly":false,"verified":null,"dashboard_id":6,"created_at":"2025-08-19T09:05:05.541818+03:00","model":"card"}', TIMESTAMP WITH TIME ZONE '2026-07-06 14:03:34.547273+06', TIMESTAMP WITH TIME ZONE '2026-07-06 14:03:34.547273+06', TRUE, TIMESTAMP WITH TIME ZONE '2025-09-04 13:28:10.220119+03', FALSE, 5, NULL, 'Registrations by State', FALSE, TIMESTAMP WITH TIME ZONE '2025-08-20 13:44:38.388228+03', 1, '[]', 6, 1, '51', 'map', TIMESTAMP WITH TIME ZONE '2025-09-04 12:33:12.351558+03', 2, 1, 24, TIMESTAMP WITH TIME ZONE '2025-08-19 09:05:05.541818+03', NULL);     
