(110, 'Administrative Areas', 'Administrative Areas {"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE\n  administrative_area_path AS (\n    -- roots\n    SELECT\n      aa.id,\n      aa.parent_id,\n      aa.name,\n      aa.name::TEXT AS administrative_area_path,\n      1 AS LEVEL\n    FROM\n      analytics.administrative_areas aa\n    WHERE\n      aa.parent_id IS NULL\n    UNION ALL\n    -- descendants\n    SELECT\n      aa.id,\n      aa.parent_id,\n      aa.name,\n      aap.administrative_area_path || '','' || aa.name,\n      aap.level + 1\n    FROM\n      analytics.administrative_areas aa\n      JOIN administrative_area_path aap ON aa.parent_id = aap.id\n  )\nSELECT\n  *\nFROM\n  administrative_area_path"}}', 'card', '{"name":"Administrative Areas","description":null,"collection_name":null}', '{"description":null,"archived":false,"display_type":"table","collection_position":null,"database_id":2,"collection_id":null,"official_collection":null,"name":"Administrative Areas","collection_name":null,"collection_authority_level":null,"creator_id":1,"updated_at":"2026-07-06T13:36:25.247734+06:00","moderated_status":null,"dataset_query":"{\"database\":2,\"type\":\"native\",\"native\":{\"template-tags\":{},\"query\":\"WITH RECURSIVE\\n  administrative_area_path AS (\\n    -- roots\\n    SELECT\\n      aa.id,\\n      aa.parent_id,\\n      aa.name,\\n      aa.name::TEXT AS administrative_area_path,\\n      1 AS LEVEL\\n    FROM\\n      analytics.administrative_areas aa\\n    WHERE\\n      aa.parent_id IS NULL\\n    UNION ALL\\n    -- descendants\\n    SELECT\\n      aa.id,\\n      aa.parent_id,\\n      aa.name,\\n      aap.administrative_area_path || '','' || aa.name,\\n      aap.level + 1\\n    FROM\\n      analytics.administrative_areas aa\\n      JOIN administrative_area_path aap ON aa.parent_id = aap.id\\n  )\\nSELECT\\n  *\\nFROM\\n  administrative_area_path\"}}","last_editor_id":1,"collection_location":null,"id":158,"last_edited_at":"2026-07-06T13:36:25.258718+06:00","dashboardcard_count":0,"collection_type":null,"display":"table","archived_directly":false,"verified":null,"dashboard_id":null,"created_at":"2026-07-06T13:36:25.247734+06:00","model":"card"}', TIMESTAMP WITH TIME ZONE '2026-07-06 14:03:34.547273+06', TIMESTAMP WITH TIME ZONE '2026-07-06 14:03:34.547273+06', FALSE, TIMESTAMP WITH TIME ZONE '2026-07-06 13:36:25.247734+06', FALSE, NULL, NULL, 'Administrative Areas', FALSE, TIMESTAMP WITH TIME ZONE '2026-07-06 13:36:25.258718+06', 0, '[]', NULL, 1, '158', 'table', TIMESTAMP WITH TIME ZONE '2026-07-06 13:36:25.247734+06', 2, 1, 1, TIMESTAMP WITH TIME ZONE '2026-07-06 13:36:25.247734+06', NULL);         
