er marital status\\":[\\"concat\\",[\\"if\\",[[[\\"=\\",[\\"field\\",\\"declaration \2192 mother_maritalStatus\\",{\\"base-type\\":\\"type/Text\\"}],\\"SINGLE\\"],\\"Single\\"]]],[\\"if\\",[[[\\"=\\",[\\"field\\",\\"declaration \2192 mother_maritalStatus\\",{\\"base-type\\":\\"type/Text\\"}],\\"MARRIED\\"],\\"Married\\"]]],[\\"if\\",[[[\\"=\\",[\\"field\\",\\"declaration \2192 mother_maritalStatus\\",{\\"base-type\\":\\"type/Text\\"}],\\"WIDOWED\\"],\\"Widowed\\"]]],[\\"if\\",[[[\\"=\\",[\\"field\\",\\"declaration \2192 mother_maritalStatus\\",{\\"base-type\\":\\"type/Text\\"}],\\"DIVORCED\\"],\\"Divorced\\"]]],[\\"if\\",[[[\\"=\\",[\\"field\\",\\"declaration \2192 mother_maritalStatus\\",{\\"base-type\\":\\"type/Text\\"}],\\"SEPARATED\\"],\\"Separated\\"]]],[\\"if\\",[[[\\"=\\",[\\"field\\",\\"declaration \2192 mother_maritalStatus\\",{\\"base-type\\":\\"type/Text\\"}],\\"NOT_STATED\\"],\\"Not stated\\"]]]],\\"Father marital status\\":[\\"concat\\",[\\"if\\",[[[\\"=\\",[\\"field\\",\\"declaration \2192 father_maritalStatus\\",{\\"base-type\\":\\"type/Text\\"}],\\"SINGLE\\"],\\"Single\\"]]],[\\"if\\",[[[\\"=\\",[\\"field\\",\\"declaration \2192 father_maritalStatus\\",{\\"base-type\\":\\"type/Text\\"}],\\"MARRIED\\"],\\"Married\\"]]],[\\"if\\",[[[\\"=\\",[\\"field\\",\\"declaration \2192 father_maritalStatus\\",{\\"base-type\\":\\"type/Text\\"}],\\"WIDOWED\\"],\\"Widowed\\"]]],[\\"if\\",[[[\\"=\\",[\\"field\\",\\"declaration \2192 father_maritalStatus\\",{\\"base-type\\":\\"type/Text\\"}],\\"DIVORCED\\"],\\"Divorced\\"]]],[\\"if\\",[[[\\"=\\",[\\"field\\",\\"declaration \2192 father_maritalStatus\\",{\\"base-type\\":\\"type/Text\\"}],\\"SEPARATED\\"],\\"Separated\\"]]],[\\"if\\",[[[\\"=\\",[\\"field\\",\\"declaration \2192 father_maritalStatus\\",{\\"base-type\\":\\"type/Text\\"}],\\"NOT_STATED\\"],\\"Not stated\\"]]]],\\"Child Birth Location Private Home\\":[\\"concat\\",[\\"case\\",[[[\\"is-empty\\",[\\"field\\",\\"administrative_area_path\\",{\\"base-type\\":\\"t