(119, 'Birth registration completeness rates by province (children under 1 year of age)', 'Birth registration completeness rates by province (children under 1 year of age)', 'card', '{"name":"Birth registration completeness rates by province (children under 1 year of age)","description":null,"collection_name":"Dashboards"}', '{"description":null,"archived":false,"display_type":"bar","collection_position":null,"database_id":2,"collection_id":8,"official_collection":null,"name":"Birth registration completeness rates by province (children under 1 year of age)","collection_name":"Dashboards","collection_authority_level":null,"creator_id":1,"updated_at":"2026-07-06T14:15:58.844096+06:00","moderated_status":null,"dataset_query":"{\"database\":2,\"type\":\"query\",\"query\":{\"expressions\":{\"Completeness Rate\":[\"case\",[[[\"is-empty\",[\"field\",\"completeness_rate\",{\"base-type\":\"type/Decimal\"}]],0]],{\"default\":[\"field\",\"completeness_rate\",{\"base-type\":\"type/Decimal\"}]}]},\"source-table\":\"card__124\",\"filter\":[\"=\",[\"field\",\"level\",{\"base-type\":\"type/Integer\"}],1]}}","last_editor_id":1,"collection_location":"/","id":126,"last_edited_at":"2026-07-06T14:15:58.923001+06:00","dashboardcard_count":1,"collection_type":null,"display":"bar","archived_directly":false,"verified":null,"dashboard_id":12,"created_at":"2025-09-12T11:23:48.72899+03:00","model":"card"}', TIMESTAMP WITH TIME ZONE '2026-07-06 14:15:59.287611+06', TIMESTAMP WITH TIME ZONE '2026-07-06 14:15:59.287611+06', FALSE, TIMESTAMP WITH TIME ZONE '2026-07-06 14:15:58.844096+06', FALSE, 8, NULL, 'Birth registration completeness rates by province (children under 1 year of age)', FALSE, TIMESTAMP WITH TIME ZONE '2026-07-06 14:15:58.923001+06', 1, '[]', 12, 1, '126', 'bar', TIMESTAMP WITH TIME ZONE '2025-10-27 13:13:39.145641+06', 2, 1, 139, TIMESTAMP WITH TIME ZONE '2025-09-12 11:23:48.72899+03', NULL),
(126, 'Births completeness rates Completeness rates per location per year, based on country provided population and crude birth rate statistics', 'Births completeness rates Completeness rates per location per year, based on country provided population and crude birth rate statistics {"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE\n  levels AS (\n    -- root = 1, children increment\n    SELECT\n      id,\n      parent_id,\n      1 AS LEVEL\n    FROM\n      analytics.administrative_areas\n    WHERE\n      parent_id IS NULL\n    UNION ALL\n    SELECT\n      l.id,\n      l.parent_id,\n      lv.level + 1\n    FROM\n      analytics.administrative_areas l\n      JOIN levels lv ON l.parent_id = lv.id\n  ),\n  -- ancestor/descendant closure: every node is ancestor of itself and all its descendants\n  closure AS (\n    SELECT\n      id AS ancestor_id,\n      id AS descendant_id\n    FROM\n      analytics.administrative_areas\n    UNION ALL\n    SELECT\n      c.ancestor_id,\n      l.id AS descendant_id\n    FROM\n      closure c\n      JOIN analytics.administrative_areas l ON l.parent_id = c.descendant_id\n  ),\n  -- counts at leaf/origin locations by year\n  counts AS (\n    SELECT\n      loc.administrative_area_id AS location_id,\n      EXTRACT(\n        YEAR\n        FROM\n          ea.created_at\n      )::int AS YEAR,\n      COUNT(*) AS cnt\n    FROM\n      analytics.event_actions ea\n      JOIN analytics.locations loc ON loc.id = ea.created_at_location\n    WHERE\n      ea.action_type = ''REGISTER''\n      AND ea.event_type = ''birth''\n      AND ea.created_at IS NOT NULL\n      AND ea.created_at_location IS NOT NULL\n      AND (ea.declaration ->> ''child_dob'')::date > ea.created_at::date - INTERVAL ''365 days''\n    GROUP BY\n      loc.administrative_area_id,\n      YEAR\n  ),\n  -- roll up descendant counts to each ancestor (this is the named query)\n  birth_registrations_per_location AS (\n    SELECT\n      c.ancestor_id AS location_id,\n      cnt.year,\n      SUM(cnt.cnt) AS register_count\n    FROM\n      closure c\n      JOIN counts cnt ON cnt.location_id = c.descendant_id\n    GROUP BY\n      c.ancestor_id,\n      cnt.year\n  )\nSELECT\n  l.id,\n  l.name,\n  s.year,\n  s.crude_birth_rate,\n  s.total_population,\n  (s.total_population / 1000 * s.crude_birth_rate) AS estimated_births,\n  COALESCE(br.register_count, 0) AS register_count,\n  COALESCE(\n    register_count / NULLIF(\n      (s.total_population / 1000 * s.crude_birth_rate),\n      0\n    ) * 100,\n    0\n  ) AS completeness_rate,\n  lv.level,\n  ll.name AS level_name\nFROM\n  analytics.administrative_areas l\n  JOIN analytics.location_statistics s ON s.name = l.name\n  LEFT JOIN birth_registrations_per_location br ON br.location_id = l.id\n  AND br.year = s.year\n  LEFT JOIN levels lv ON lv.id = l.id\n  LEFT JOIN analytics.location_levels ll ON ll.level = lv.level\nORDER BY\n  s.year DESC,\n  register_count DESC;"}}', 'dataset', '{"name":"Births completeness rates","description":"Completeness rates per location per year, based on country provided population and crude birth rate statistics","collection_name":"Births"}', '{"description":"Completeness rates per location per year, based on country provided population and crude birth rate statistics","archived":false,"display_type":"table","collection_position":1,"database_id":2,"collection_id":9,"official_collection":null,"name":"Births completeness rates","collection_name":"Births","collection_authority_level":null,"creator_id":1,"updated_at":"2026-07-06T14:27:39.684624+06:00","moderated_status":null,"dataset_query":"{\"database\":2,\"type\":\"native\",\"native\":{\"template-tags\":{},\"query\":\"WITH RECURSIVE\\n  levels AS (\\n    -- root = 1, children increment\\n    SELECT\\n      id,\\n      parent_id,\\n      1 AS LEVEL\\n    FROM\\n      analytics.administrative_areas\\n    WHERE\\n      parent_id IS NULL\\n    UNION ALL\\n    SELECT\\n      l.id,\\n      l.parent_id,\\n      lv.level + 1\\n    FROM\\n      analytics.administrative_areas l\\n      JOIN levels lv ON l.parent_id = lv.id\\n  ),\\n  -- ancestor/descendant closure: every node is ancestor of itself and all its descendants\\n  closure AS (\\n    SELECT\\n      id AS ancestor_id,\\n      id AS descendant_id\\n    FROM\\n      analytics.administrative_areas\\n    UNION ALL\\n    SELECT\\n      c.ancestor_id,\\n      l.id AS descendant_id\\n    FROM\\n      closure c\\n      JOIN analytics.administrative_areas l ON l.parent_id = c.descendant_id\\n  ),\\n  -- counts at leaf/origin locations by year\\n  counts AS (\\n    SELECT\\n      loc.administrative_area_id AS location_id,\\n      EXTRACT(\\n        YEAR\\n        FROM\\n          ea.created_at\\n      )::int AS YEAR,\\n      COUNT(*) AS cnt\\n    FROM\\n      analytics.event_actions ea\\n      JOIN analytics.locations loc ON loc.id = ea.created_at_location\\n    WHERE\\n      ea.action_type = ''REGISTER''\\n      AND ea.event_type = ''birth''\\n      AND ea.created_at IS NOT NULL\\n      AND ea.created_at_location IS NOT NULL\\n      AND (ea.declaration ->> ''child_dob'')::date > ea.created_at::date - INTERVAL ''365 days''\\n    GROUP BY\\n      loc.administrative_area_id,\\n      YEAR\\n  ),\\n  -- roll up descendant counts to each ancestor (this is the named query)\\n  birth_registrations_per_location AS (\\n    SELECT\\n      c.ancestor_id AS location_id,\\n      cnt.year,\\n      SUM(cnt.cnt) AS register_count\\n    FROM\\n      closure c\\n      JOIN counts cnt ON cnt.location_id = c.descendant_id\\n    GROUP BY\\n      c.ancestor_id,\\n      cnt.year\\n  )\\nSELECT\\n  l.id,\\n  l.name,\\n  s.year,\\n  s.crude_birth_rate,\\n  s.total_population,\\n  (s.total_population / 1000 * s.crude_birth_rate) AS estimated_births,\\n  COALESCE(br.register_count, 0) AS register_count,\\n  COALESCE(\\n    register_count / NULLIF(\\n      (s.total_population / 1000 * s.crude_birth_rate),\\n      0\\n    ) * 100,\\n    0\\n  ) AS completeness_rate,\\n  lv.level,\\n  ll.name AS level_name\\nFROM\\n  analytics.administrative_areas l\\n  JOIN analytics.location_statistics s ON s.name = l.name\\n  LEFT JOIN birth_registrations_per_location br ON br.location_id = l.id\\n  AND br.year = s.year\\n  LEFT JOIN levels lv ON lv.id = l.id\\n  LEFT JOIN analytics.location_levels ll ON ll.level = lv.level\\nORDER BY\\n  s.year DESC,\\n  register_count DESC;\"}}","last_editor_id":1,"collection_location":"/6/","id":124,"last_edited_at":"2026-07-06T14:27:39.712943+06:00","dashboardcard_count":0,"collection_type":null,"display":"table","archived_directly":false,"verified":null,"dashboard_id":null,"created_at":"2025-09-12T10:07:18.436943+03:00","model":"dataset"}', TIMESTAMP WITH TIME ZONE '2026-07-06 14:27:40.948332+06', TIMESTAMP WITH TIME ZONE '2026-07-06 14:27:40.948332+06', FALSE, TIMESTAMP WITH TIME ZONE '2026-07-06 14:27:39.684624+06', TRUE, 9, NULL, 'Births completeness rates', FALSE, TIMESTAMP WITH TIME ZONE '2026-07-06 14:27:39.712943+06', 0, '[]', NULL, 1, '124', 'table', TIMESTAMP WITH TIME ZONE '2026-07-06 14:26:56.847682+06', 2, 1, 93, TIMESTAMP WITH TIME ZONE '2025-09-12 10:07:18.436943+03', NULL);          
