(131, 'Completeness rate', 'Completeness rate {"database":2,"type":"native","native":{"template-tags":{"year":{"id":"be1ae479-6da3-4c17-b7fe-e412a701c0b7","type":"number","name":"year","display-name":"Year","default":"2026"}},"query":"WITH\n  top_level_locations AS (\n    SELECT\n      name\n    FROM\n      analytics.administrative_areas\n    WHERE\n      parent_id IS NULL\n  ),\n  population_sum AS (\n    SELECT\n      SUM(total_population) AS total_population\n    FROM\n      analytics.location_statistics s\n      JOIN top_level_locations l ON s.name = l.name [[WHERE\n      s.year ={{year}}]]\n  ),\n  birth_rate AS (\n    SELECT\n      AVG(crude_birth_rate) AS country_birth_rate\n    FROM\n      analytics.location_statistics [[    WHERE\n      YEAR ={{year}}]]\n  ),\n  registered_births AS (\n    SELECT\n      COUNT(*) AS registered_count\n    FROM\n      analytics.event_actions\n    WHERE\n      action_type = ''REGISTER''\n      AND event_type = ''birth''\n      AND (\n        created_at::date - (declaration ->> ''child_dob'')::date\n      ) < 365 [[AND EXTRACT(\n    YEAR FROM created_at::date\n) = {{year}}]]\n  )\nSELECT\n  r.registered_count / (p.total_population / 1000 * b.country_birth_rate) * 100 AS registered_birth_percentage\nFROM\n  registered_births r,\n  birth_rate b,\n  population_sum p;"}}', 'card', '{"name":"Completeness rate","description":null,"collection_name":"Dashboards"}', '{"description":null,"archived":false,"display_type":"gauge","collection_position":null,"database_id":2,"collection_id":8,"official_collection":null,"name":"Completeness rate","collection_name":"Dashboards","collection_authority_level":null,"creator_id":1,"updated_at":"2026-07-06T14:15:06.020551+06:00","moderated_status":null,"dataset_query":"{\"database\":2,\"type\":\"native\",\"native\":{\"template-tags\":{\"year\":{\"id\":\"be1ae479-6da3-4c17-b7fe-e412a701c0b7\",\"type\":\"number\",\"name\":\"year\",\"display-name\":\"Year\",\"default\":\"2026\"}},\"query\":\"WITH\\n  top_level_locations AS (\\n    SELECT\\n      name\\n    FROM\\n      analytics.administrative_areas\\n    WHERE\\n      parent_id IS NULL\\n  ),\\n  population_sum AS (\\n    SELECT\\n      SUM(total_population) AS total_population\\n    FROM\\n      analytics.location_statistics s\\n      JOIN top_level_locations l ON s.name = l.name [[WHERE\\n      s.year ={{year}}]]\\n  ),\\n  birth_rate AS (\\n    SELECT\\n      AVG(crude_birth_rate) AS country_birth_rate\\n    FROM\\n      analytics.location_statistics [[    WHERE\\n      YEAR ={{year}}]]\\n  ),\\n  registered_births AS (\\n    SELECT\\n      COUNT(*) AS registered_count\\n    FROM\\n      analytics.event_actions\\n    WHERE\\n      action_type = ''REGISTER''\\n      AND event_type = ''birth''\\n      AND (\\n        created_at::date - (declaration ->> ''child_dob'')::date\\n      ) < 365 [[AND EXTRACT(\\n    YEAR FROM created_at::date\\n) = {{year}}]]\\n  )\\nSELECT\\n  r.registered_count / (p.total_population / 1000 * b.country_birth_rate) * 100 AS registered_birth_percentage\\nFROM\\n  registered_births r,\\n  birth_rate b,\\n  population_sum p;\"}}","last_editor_id":1,"collection_location":"/","id":156,"last_edited_at":"2026-07-06T14:15:06.106584+06:00","dashboardcard_count":1,"collection_type":null,"display":"gauge","archived_directly":false,"verified":null,"dashboard_id":12,"created_at":"2025-10-16T09:28:43.241794+03:00","model":"card"}', TIMESTAMP WITH TIME ZONE '2026-07-06 14:28:11.030784+06', TIMESTAMP WITH TIME ZONE '2026-07-06 14:28:11.030784+06', FALSE, TIMESTAMP WITH TIME ZONE '2026-07-06 14:15:06.020551+06', FALSE, 8, NULL, 'Completeness rate', FALSE, TIMESTAMP WITH TIME ZONE '2026-07-06 14:15:06.106584+06', 1, '[]', 12, 1, '156', 'gauge', TIMESTAMP WITH TIME ZONE '2026-07-06 14:26:56.847682+06', 2, 1, 31, TIMESTAMP WITH TIME ZONE '2025-10-16 09:28:43.241794+03', NULL),
