(139, 'Locations', 'Locations {"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE\n  administrative_area_path AS (\n    -- roots\n    SELECT\n      aa.id,\n      aa.parent_id,\n      aa.name,\n      aa.name::TEXT AS administrative_area_path,\n      1 AS LEVEL\n    FROM\n      analytics.administrative_areas aa\n    WHERE\n      aa.parent_id IS NULL\n    UNION ALL\n    -- descendants\n    SELECT\n      aa.id,\n      aa.parent_id,\n      aa.name,\n      aap.administrative_area_path || '','' || aa.name,\n      aap.level + 1\n    FROM\n      analytics.administrative_areas aa\n      JOIN administrative_area_path aap ON aa.parent_id = aap.id\n  ),\n  pivot AS (\n    SELECT\n      id,\n      split_part(administrative_area_path, '','', 1) AS level_1_name,\n      split_part(administrative_area_path, '','', 2) AS level_2_name,\n      split_part(administrative_area_path, '','', 3) AS level_3_name,\n      split_part(administrative_area_path, '','', 4) AS level_4_name,\n      split_part(administrative_area_path, '','', 5) AS level_5_name,\n      split_part(administrative_area_path, '','', 6) AS level_6_name,\n      split_part(administrative_area_path, '','', 7) AS level_7_name,\n      split_part(administrative_area_path, '','', 8) AS level_8_name,\n      split_part(administrative_area_path, '','', 9) AS level_9_name,\n      split_part(administrative_area_path, '','', 10) AS level_10_name\n    FROM\n      administrative_area_path\n  )\nSELECT\n  l.id::TEXT AS id,\n  l.name,\n  l.location_type,\n  l.administrative_area_id,\n  aa.name AS administrative_area_name,\n  aap.administrative_area_path,\n  aap.level AS administrative_area_level,\n  -- include location itself in the final full path\n  CASE\n    WHEN aap.administrative_area_path IS NOT NULL THEN aap.administrative_area_path || '','' || l.name\n    ELSE l.name\n  END AS full_path,\n  p.level_1_name,\n  p.level_2_name,\n  p.level_3_name,\n  p.level_4_name,\n  p.level_5_name,\n  p.level_6_name,\n  p.level_7_name,\n  p.level_8_name,\n  p.level_9_name,\n  p.level_10_name\nFROM\n  analytics.locations l\n  LEFT JOIN analytics.administrative_areas aa ON aa.id = l.administrative_area_id\n  LEFT JOIN administrative_area_path aap ON aap.id = aa.id\n  LEFT JOIN pivot p ON p.id = aa.id;"}}', 'dataset', '{"name":"Locations","description":null,"collection_name":null}', '{"description":null,"archived":false,"display_type":"table","collection_position":10,"database_id":2,"collection_id":null,"official_collection":null,"name":"Locations","collection_name":null,"collection_authority_level":null,"creator_id":1,"updated_at":"2026-07-07T13:18:28.880083+06:00","moderated_status":null,"dataset_query":"{\"database\":2,\"type\":\"native\",\"native\":{\"template-tags\":{},\"query\":\"WITH RECURSIVE\\n  administrative_area_path AS (\\n    -- roots\\n    SELECT\\n      aa.id,\\n      aa.parent_id,\\n      aa.name,\\n      aa.name::TEXT AS administrative_area_path,\\n      1 AS LEVEL\\n    FROM\\n      analytics.administrative_areas aa\\n    WHERE\\n      aa.parent_id IS NULL\\n    UNION ALL\\n    -- descendants\\n    SELECT\\n      aa.id,\\n      aa.parent_id,\\n      aa.name,\\n      aap.administrative_area_path || '','' || aa.name,\\n      aap.level + 1\\n    FROM\\n      analytics.administrative_areas aa\\n      JOIN administrative_area_path aap ON aa.parent_id = aap.id\\n  ),\\n  pivot AS (\\n    SELECT\\n      id,\\n      split_part(administrative_area_path, '','', 1) AS level_1_name,\\n      split_part(administrative_area_path, '','', 2) AS level_2_name,\\n      split_part(administrative_area_path, '','', 3) AS level_3_name,\\n      split_part(administrative_area_path, '','', 4) AS level_4_name,\\n      split_part(administrative_area_path, '','', 5) AS level_5_name,\\n      split_part(administrative_area_path, '','', 6) AS level_6_name,\\n      split_part(administrative_area_path, '','', 7) AS level_7_name,\\n      split_part(administrative_area_path, '','', 8) AS level_8_name,\\n      split_part(administrative_area_path, '','', 9) AS level_9_name,\\n      split_part(administrative_area_path, '','', 10) AS level_10_name\\n    FROM\\n      administrative_area_path\\n  )\\nSELECT\\n  l.id::TEXT AS id,\\n  l.name,\\n  l.location_type,\\n  l.administrative_area_id,\\n  aa.name AS administrative_area_name,\\n  aap.administrative_area_path,\\n  aap.level AS administrative_area_level,\\n  -- include location itself in the final full path\\n  CASE\\n    WHEN aap.administrative_area_path IS NOT NULL THEN aap.administrative_area_path || '','' || l.name\\n    ELSE l.name\\n  END AS full_path,\\n  p.level_1_name,\\n  p.level_2_name,\\n  p.level_3_name,\\n  p.level_4_name,\\n  p.level_5_name,\\n  p.level_6_name,\\n  p.level_7_name,\\n  p.level_8_name,\\n  p.level_9_name,\\n  p.level_10_name\\nFROM\\n  analytics.locations l\\n  LEFT JOIN analytics.administrative_areas aa ON aa.id = l.administrative_area_id\\n  LEFT JOIN administrative_area_path aap ON aap.id = aa.id\\n  LEFT JOIN pivot p ON p.id = aa.id;\"}}","last_editor_id":1,"collection_location":null,"id":71,"last_edited_at":"2026-07-07T13:18:28.985262+06:00","dashboardcard_count":0,"collection_type":null,"display":"table","archived_directly":false,"verified":null,"dashboard_id":null,"created_at":"2025-09-04T13:31:14.91944+03:00","model":"dataset"}', TIMESTAMP WITH TIME ZONE '2026-07-07 13:18:29.639783+06', TIMESTAMP WITH TIME ZONE '2026-07-07 13:18:29.639783+06', FALSE, TIMESTAMP WITH TIME ZONE '2026-07-07 13:18:28.880083+06', TRUE, NULL, NULL, 'Locations', FALSE, TIMESTAMP WITH TIME ZONE '2026-07-07 13:18:28.985262+06', 0, '[]', NULL, 1, '71', 'table', TIMESTAMP WITH TIME ZONE '2026-07-07 13:17:46.779197+06', 2, 1, 89, TIMESTAMP WITH TIME ZONE '2025-09-04 13:31:14.91944+03', NULL);           
