(108, 'Description block', 'Description block {"database":2,"type":"native","native":{"template-tags":{"my_param":{"type":"text","name":"my_param","id":"4effb4b1-3400-40fd-b19d-9dc6f2fb9224","display-name":"My Param","default":"Test"}},"query":"SELECT {{my_param}} AS title"}}', 'card', '{"name":"Description block","description":null,"collection_name":"Dashboards"}', '{"description":null,"archived":true,"display_type":"scalar","collection_position":null,"database_id":2,"collection_id":8,"official_collection":null,"name":"Description block","collection_name":"Dashboards","collection_authority_level":null,"creator_id":1,"updated_at":"2025-09-15T10:24:01.329652+03:00","moderated_status":null,"dataset_query":"{\"database\":2,\"type\":\"native\",\"native\":{\"template-tags\":{\"my_param\":{\"type\":\"text\",\"name\":\"my_param\",\"id\":\"4effb4b1-3400-40fd-b19d-9dc6f2fb9224\",\"display-name\":\"My Param\",\"default\":\"Test\"}},\"query\":\"SELECT {{my_param}} AS title\"}}","last_editor_id":1,"collection_location":"/","id":129,"last_edited_at":"2025-09-15T09:44:16.706617+03:00","dashboardcard_count":0,"collection_type":null,"display":"scalar","archived_directly":true,"verified":null,"dashboard_id":11,"created_at":"2025-09-15T09:39:46.444299+03:00","model":"card"}', TIMESTAMP WITH TIME ZONE '2026-07-06 13:03:34.482098+06', TIMESTAMP WITH TIME ZONE '2026-07-06 13:03:34.482098+06', TRUE, TIMESTAMP WITH TIME ZONE '2025-09-15 10:24:01.329652+03', FALSE, 8, NULL, 'Description block', FALSE, TIMESTAMP WITH TIME ZONE '2025-09-15 09:44:16.706617+03', 0, '[]', 11, 1, '129', 'scalar', TIMESTAMP WITH TIME ZONE '2025-09-15 10:12:35.843653+03', 2, 1, 26, TIMESTAMP WITH TIME ZONE '2025-09-15 09:39:46.444299+03', NULL),
(109, 'Completeness rate', 'Completeness rate {"database":2,"type":"native","native":{"template-tags":{"year":{"id":"be1ae479-6da3-4c17-b7fe-e412a701c0b7","type":"number","name":"year","display-name":"Year"}},"query":"WITH top_level_locations AS (\n  SELECT name\n  FROM analytics.locations\n  WHERE parent_id IS NULL\n),\npopulation_sum AS (\n  SELECT \n    SUM(total_population) AS total_population\n  FROM \n    analytics.location_statistics s\n  JOIN \n    top_level_locations l ON s.name = l.name\n  WHERE \n    s.year = [[{{year}}]]\n),\nbirth_rate AS (\n  SELECT \n    AVG(crude_birth_rate) AS country_birth_rate\n  FROM \n    analytics.location_statistics\n  WHERE \n    year = [[{{year}}]]\n),\nregistered_births AS (\n  SELECT \n    COUNT(*) AS registered_count\n  FROM \n    analytics.event_actions\n  WHERE \n    action_type = ''REGISTER''\n    AND event_type = ''birth''\n    AND (created_at::date - (declaration->>''child_dob'')::date) < 365\n)\nSELECT \n  r.registered_count / (p.total_population / 1000 * b.country_birth_rate) * 100 AS registered_birth_percentage\nFROM \n  registered_births r,\n  birth_rate b,\n  population_sum p;"}}', 'card', '{"name":"Completeness rate","description":null,"collection_name":"Dashboards"}', '{"description":null,"archived":false,"display_type":"gauge","collection_position":null,"database_id":2,"collection_id":8,"official_collection":null,"name":"Completeness rate","collection_name":"Dashboards","collection_authority_level":null,"creator_id":1,"updated_at":"2025-10-17T14:27:54.392077+03:00","moderated_status":null,"dataset_query":"{\"database\":2,\"type\":\"native\",\"native\":{\"template-tags\":{\"year\":{\"id\":\"be1ae479-6da3-4c17-b7fe-e412a701c0b7\",\"type\":\"number\",\"name\":\"year\",\"display-name\":\"Year\"}},\"query\":\"WITH top_level_locations AS (\\n  SELECT name\\n  FROM analytics.locations\\n  WHERE parent_id IS NULL\\n),\\npopulation_sum AS (\\n  SELECT \\n    SUM(total_population) AS total_population\\n  FROM \\n    analytics.location_statistics s\\n  JOIN \\n    top_level_locations l ON s.name = l.name\\n  WHERE \\n    s.year = [[{{year}}]]\\n),\\nbirth_rate AS (\\n  SELECT \\n    AVG(crude_birth_rate) AS country_birth_rate\\n  FROM \\n    analytics.location_statistics\\n  WHERE \\n    year = [[{{year}}]]\\n),\\nregistered_births AS (\\n  SELECT \\n    COUNT(*) AS registered_count\\n  FROM \\n    analytics.event_actions\\n  WHERE \\n    action_type = ''REGISTER''\\n    AND event_type = ''birth''\\n    AND (created_at::date - (declaration->>''child_dob'')::date) < 365\\n)\\nSELECT \\n  r.registered_count / (p.total_population / 1000 * b.country_birth_rate) * 100 AS registered_birth_percentage\\nFROM \\n  registered_births r,\\n  birth_rate b,\\n  population_sum p;\"}}","last_editor_id":1,"collection_location":"/","id":156,"last_edited_at":"2025-10-17T14:27:54.401785+03:00","dashboardcard_count":1,"collection_type":null,"display":"gauge","archived_directly":false,"verified":null,"dashboard_id":12,"created_at":"2025-10-16T09:28:43.241794+03:00","model":"card"}', TIMESTAMP WITH TIME ZONE '2026-07-06 13:03:34.482098+06', TIMESTAMP WITH TIME ZONE '2026-07-06 13:03:34.482098+06', FALSE, TIMESTAMP WITH TIME ZONE '2025-10-17 14:27:54.392077+03', FALSE, 8, NULL, 'Completeness rate', FALSE, TIMESTAMP WITH TIME ZONE '2025-10-17 14:27:54.401785+03', 1, '[]', 12, 1, '156', 'gauge', TIMESTAMP WITH TIME ZONE '2025-10-27 13:13:39.145641+06', 2, 1, 23, TIMESTAMP WITH TIME ZONE '2025-10-16 09:28:43.241794+03', NULL);        
